window.MOEX_PRACTICE = {"modules": [{"id": 1, "name": "腎臟系統", "count": 43}, {"id": 2, "name": "體液電解質及酸鹼平衡", "count": 27}, {"id": 3, "name": "腎臟與泌尿系統", "count": 62}, {"id": 4, "name": "內分泌系統", "count": 124}, {"id": 5, "name": "血液與免疫系統", "count": 102}, {"id": 6, "name": "生殖系統", "count": 22}, {"id": 7, "name": "眼耳鼻喉", "count": 49}, {"id": 8, "name": "皮膚", "count": 37}, {"id": 9, "name": "急症護理", "count": 58}], "pools": {"1": [{"id": "106030-106-0503-064", "year": 106, "session": "第一次", "no": 64, "stem": "64 臨床上最可以早期診斷慢性腎絲球腎炎之檢查，下列何者正確？", "options": ["靜脈腎盂攝影（IVP）", "酚紅試驗（PSP）", "肌酸酐廓清試驗（CCr）", "腎臟活體組織切片"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-058", "year": 106, "session": "第二次", "no": 58, "stem": "58 下列何者為檢測腎絲球過濾率的最佳指標？", "options": ["尿液培養", "腎臟、輸尿管、膀胱攝影", "肌酸酐廓清率", "酚紅試驗"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-063", "year": 106, "session": "第二次", "no": 63, "stem": "63 有關腎前性急性腎衰竭之檢驗數據，下列何者錯誤？", "options": ["血液尿素氮與肌酸酐的比>20：1", "尿鈉離子濃度>40 mEg/L", "尿比重>1.015", "尿滲透壓增加至500 mOsm/L"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-079", "year": 106, "session": "第二次", "no": 79, "stem": "79 楊先生50 歲，患有高血壓超過10 年，目前被診斷有慢性腎疾病，為減緩腎功能衰退，應指導其血\n\n  壓控制在下列何種範圍？", "options": ["130/85 mmHg 以下", "140～145/85～90 mmHg", "145～150/90～95 mmHg", "視病人情況而定"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-066", "year": 106, "session": "第二次", "no": 66, "stem": "66 有關急性間質性腎炎之敘述，下列何者錯誤？", "options": ["常因對某些藥物（如：抗生素）過敏而發生", "可能出現急性腎衰竭", "必須長期接受透析治療", "通常停用導致過敏的藥物後，腎功能可恢復正常"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-063", "year": 107, "session": "第一次", "no": 63, "stem": "63 有關腎盂腎炎之敘述，下列何者錯誤？", "options": ["常見於下泌尿道上行性感染", "C-反應蛋白質（C-Reactive Protein, CRP）值會增高", "常見有肋骨脊柱角處疼痛", "急性期時應限制液體攝取量"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-064", "year": 107, "session": "第一次", "no": 64, "stem": "64 有關急性腎絲球腎炎之敘述，下列何者錯誤？", "options": ["常由β 型溶血性鏈球菌感染引起", "是抗原抗體反應造成的疾病", "C3 與 C4 補體值會上升", "需長期接受Penicillin 治療"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-065", "year": 107, "session": "第一次", "no": 65, "stem": "65  有關早期慢性腎臟病病人服用血管收縮素轉化酶抑制劑（Angiotensin Converting Enzyme Inhibitors,\n\n   ACEI）之敘述，下列何者錯誤？", "options": ["可預防蛋白尿之產生", "易有乾咳副作用", "可能導致低血壓", "可能導致低血鉀"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-066", "year": 107, "session": "第一次", "no": 66, "stem": "66 慢性腎臟病（CKD）病人之抽血檢查結果：GFR: 20c.c./min/1.73m2、serum Creatinine: 8.0 mg/dL，依\n\n  此結果，病人是處於CKD 的第幾期？", "options": ["第二期", "第三期", "第四期", "第五期"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107110-106-0503-060", "year": 107, "session": "第二次", "no": 60, "stem": "60 有關腎移植後產生的排斥現象，下列何者預後最佳？", "options": ["慢性", "急性", "超急性", "加速型"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107110-106-0503-062", "year": 107, "session": "第二次", "no": 62, "stem": "62 有關急性腎絲球腎炎病人之護理指導，下列何者正確？", "options": ["出現喉嚨痛或皮膚感染時應早期接受治療", "出現上呼吸道感染時即須服用抗生素", "須長期服用預防性抗生素以避免疾病復發", "須監測呼吸情況，因疾病會侵犯呼吸道黏膜引起呼吸衰竭"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107110-106-0503-067", "year": 107, "session": "第二次", "no": 67, "stem": "67 有關血液透析不平衡症候群之敘述，下列何者正確？", "options": ["最常發生於多次透析療程之後", "可能因血液中尿素氮減少的速度比腦部慢所致", "會產生滲透壓不平衡，導致腦脫水、缺氧", "會出現神經症狀，如不安、意識程度降低、抽搐"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107110-106-0503-068", "year": 107, "session": "第二次", "no": 68, "stem": "68 有關慢性腎衰竭典型之合併症，不包括下列何項？", "options": ["貧血", "胃腸出血", "月經不規則", "副甲狀腺功能低下"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-064", "year": 108, "session": "第一次", "no": 64, "stem": "64 有關腎病症候群病人之處置，下列何者錯誤？", "options": ["採低鈉、低鉀、低蛋白飲食", "使用Prednisolone 以緩解蛋白尿", "給予Furosemide（Lasix）用以控制水腫", "使用抗凝劑預防腎靜脈血栓"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-065", "year": 108, "session": "第一次", "no": 65, "stem": "65 有關急性腎絲球腎炎（AGN）急性期之護理指導，下列何者正確？①多下床活動以避免下肢水腫\n  ②採高碳水化合物、低蛋白飲食 ③預防感染措施 ④鼓勵多喝水", "options": ["①②", "①④", "②③", "③④"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-066", "year": 108, "session": "第一次", "no": 66, "stem": "66  有關接受腎移植而服用免疫抑制劑cyclosporine 之敘述，下列何者錯誤？", "options": ["避免進出公共場所", "可能會出現肝、腎毒性", "長期服用易致癌症", "腎功能維持穩定正常後，即可停藥"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-080", "year": 108, "session": "第一次", "no": 80, "stem": "80  有關GFR 為15 mL/min/1.73 m2 之慢性腎臟病病人之護理指導，下列何者最適當？", "options": ["介紹阻緩腎功能惡化的措施", "介紹腎臟疾病相關知識", "介紹透析治療通路", "介紹透析治療合併症"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108110-106-0503-066", "year": 108, "session": "第二次", "no": 66, "stem": "66 有關腎盂腎炎的敘述，下列何者錯誤？", "options": ["糖尿病、尿路結石是其危險因子", "C 反應蛋白質（CRP）值會增高", "會有肋骨脊柱角處疼痛", "急性期時應限制液體攝取量"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-056", "year": 109, "session": "第一次", "no": 56, "stem": "56 蔡先生因急性腎衰竭而住院，正處於少尿期，下列何項護理指導正確？", "options": ["應採低熱量飲食", "應限制高鈉高磷之食物", "應採高蛋白飲食", "採高鉀飲食"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-057", "year": 109, "session": "第一次", "no": 57, "stem": "57  王先生因急性腎衰竭而急診入院，目前檢驗測得arterial blood gas 為pH：7.23，PaCO2：32 mmHg，\n    HCO3 －：17.5 mEq/L，PaO2：82 mmHg，SaO2：98%，此結果屬：", "options": ["呼吸性酸中毒", "部分代償性呼吸性酸中毒", "代謝性酸中毒", "部分代償性代謝性酸中毒"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-059", "year": 109, "session": "第一次", "no": 59, "stem": "59 有關急性腎盂腎炎之敘述，下列何者正確？①常見於下泌尿道上行性感染 ②常見有肋骨脊柱角處\n  疼痛 ③紅血球沉降速率（ESR）下降 ④急性期時應大量攝取液體", "options": ["①②③", "①②④", "①③④", "②③④"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-060", "year": 109, "session": "第一次", "no": 60, "stem": "60 血液透析病人之液體攝取量的估計原則，下列何者最適當？", "options": ["前一日尿量加排汗量", "取決於下肢水腫程度", "兩次透析間體重增加以不超過其乾體重5%", "兩次透析間體重增加必須控制在2.0 公斤以內"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-062", "year": 109, "session": "第二次", "no": 62, "stem": "62 有關導致腎病症候群病人全身水腫之病理機轉，下列何者正確？", "options": ["因鈉離子滯留導致血管內靜力壓上升", "因腎上腺功能不足而使醛固酮（aldosterone）分泌減少", "腎絲球過濾率下降導致水分滯留", "腎絲球通透性增加使蛋白質流失而導致白蛋白減少"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-063", "year": 109, "session": "第二次", "no": 63, "stem": "63 有關腎病症候群病人之診斷性檢查之典型發現，下列何者正確？①血尿 ②菌尿 ③蛋白尿 ④血清\n  白蛋白濃度下降 ⑤血糖上升 ⑥血清膽固醇上升 ⑦血清三酸甘油酯上升 ⑧血清鈣上升", "options": ["①②④⑧", "①⑤⑥⑧", "②③⑤⑦", "③④⑥⑦"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-067", "year": 109, "session": "第二次", "no": 67, "stem": "67 關於持續可攜帶式腹膜透析（CAPD）與血液透析（HD）治療的比較，下列何者正確？", "options": ["CAPD 治療需要較嚴格的飲食控制", "CAPD 需擔負較多的自我照顧活動", "CAPD 易出現頭痛、噁心、嘔吐、低血壓症候群", "CAPD 對心臟血管方面的影響較大\n代號：3106\n頁次：6－6"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-061", "year": 110, "session": "第一次", "no": 61, "stem": "61 有關血液透析（HD）與持續可攜帶式腹膜透析（CAPD）治療的敘述，下列何者錯誤？", "options": ["HD 較CAPD 蛋白質流失較多", "CAPD 需承擔較多的自我照顧活動", "CAPD 易發生血中三酸甘油脂增加", "HD 過程，易發生低血壓及頭痛、抽筋不平衡症候群"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-065", "year": 110, "session": "第一次", "no": 65, "stem": "65 有關腎病症候群之照護措施，下列何者錯誤？", "options": ["嚴重水腫時，鼓勵多下床活動，增加水分排除", "當腎功能正常時，可採高蛋白、高熱量飲食", "指導抗凝劑使用的注意事項，如出血徵兆", "每日需監測輸入輸出量、體重及腹圍變化\n代號：3104\n頁次：6－6"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-074", "year": 110, "session": "第一次", "no": 74, "stem": "74 長期接受血液透析的病人，突然意識改變、出現抽筋及肌肉無力情況，入急診求治，抽血檢查結果：\n   尿素氮／肌酸酐120 mg/dL／10.6 mg/dL、鉀離子7.8 mg/dL、鈉離子135 mg/dL，動脈血液氣體分析\n                                                                                           _\n   結果：pH 7.28、PaO270 mmHg、PaCO2 30 mmHg、 HCO 3  20 mEq/L。下列判斷何者正確？", "options": ["未代償性呼吸性酸中毒", "部分代償性代謝性酸中毒", "完全代償性呼吸性鹼中毒", "未代償性代謝性鹼中毒"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-061", "year": 110, "session": "第二次", "no": 61, "stem": "61 有關急性腎絲球腎炎的敘述，下列何者錯誤？", "options": ["是抗原抗體反應造成的免疫性疾病", "會出現蛋白尿、血尿", "補體（C3 與C4）值會上升", "腎絲球過濾率（GFR）會下降"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-066", "year": 110, "session": "第二次", "no": 66, "stem": "66 引起代謝性酸中毒的原因，下列何者正確？①延腦異常 ②急性腎衰竭 ③肺擴張不全 ④血糖過高", "options": ["①②", "①③", "②④", "③④"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-067", "year": 110, "session": "第二次", "no": 67, "stem": "67 有關腎移植後的急性排斥徵候，不包括下列何者？", "options": ["血壓上升", "尿量減少", "血清肌酸酐值升高", "體重下降"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111030-104-0303-061", "year": 111, "session": "第一次", "no": 61, "stem": "61 林小姐食慾不振，嚴重水腫，無法平躺睡覺，至某醫學中心就診，抽血檢查結果血清\n     Creatinine=13.8 mg/dL，eGFR=9.2 mL/min/1.73 m2，依此結果，林小姐是處於慢性腎臟病（CKD）的\n  第幾期？", "options": ["第二期", "第三期", "第四期", "第五期"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111030-104-0303-067", "year": 111, "session": "第一次", "no": 67, "stem": "67 有關慢性腎衰竭的典型臨床表徵，下列何者錯誤？", "options": ["氮血症", "高血脂", "低血磷", "代謝性酸中毒"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-060", "year": 111, "session": "第二次", "no": 60, "stem": "60 王先生因慢性腎臟病正服用血管收縮素轉化酶抑制劑（ACEI），有關ACEI 的敘述，下列何者錯誤？.", "options": ["可預防蛋白尿之產生", "易有乾咳副作用", "可能導致低血壓", "可能導致低血鉀"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "112110-102-0203-061", "year": 112, "session": "第二次", "no": 61, "stem": "61 有關慢性腎絲球腎炎之敘述，下列何者正確？①肌酸酐清除率（CCr.）數值異常上升 ②血尿素氮及\n\n  血肌酸酐的數值會異常升高 ③可由經皮腎臟組織切片檢查早期確診 ④腎皮質變厚及腎臟變大", "options": ["①②", "①④", "②③", "③④"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112110&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112110-102-0203-062", "year": 112, "session": "第二次", "no": 62, "stem": "62 有關腎病症候群之臨床表徵，下列何者正確？①高白蛋白血症 ②出現蛋白尿 ③高血脂症 ④血中\n\n  膠體滲透壓上升", "options": ["①④", "②③", "①②", "③④"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112110&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112180-101-0103-039", "year": 112, "session": "第三次", "no": 39, "stem": "39 慢性腎臟病第四期病人解血尿懷疑是腎臟結石，下列診斷檢查何者最適當？", "options": ["腹部超音波", "腎動脈攝影", "逆行性腎盂攝影", "膀胱鏡檢查\n代號：3101\n頁次：4－4"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "113100-102-0203-041", "year": 113, "session": "第二次", "no": 41, "stem": "41 同時會出現在腎病症候群與急性腎絲球腎炎之臨床表徵，下列何者正確？①水腫 ②高血脂 ③蛋白尿 ④血尿", "options": ["①③", "①④", "②③", "②④"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "113180-101-0103-038", "year": 113, "session": "第三次", "no": 38, "stem": "38 有關腹膜透析治療之敘述，下列何者正確？", "options": ["透析過程易有噁心、嘔吐、低血壓不平衡症候群", "持續脫水影響血壓變化波動易造成心臟負擔較大", "觀察透析液為清澈無色", "心臟功能不佳或腦血管疾病病人不合適選用"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "114100-102-0203-038", "year": 114, "session": "第二次", "no": 38, "stem": "38 有關血液透析病人動靜脈瘻管（A-V fistula）之護理措施，下列何者正確？", "options": ["觸診瘻管摸到血流雜聲，表此處可能阻塞應速處理", "每天測量動靜脈瘻管手臂之血壓，以評估血循狀況", "可運用彈性繃帶包紮或著長袖彈力衣，以保護瘻管", "教導執行握球運動強化血管，以促進瘻管的血流量"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "115100-102-0203-039", "year": 115, "session": "第二次", "no": 39, "stem": "39 有關血液透析病人動靜脈瘻管的敘述，下列何者最適當？", "options": ["聽診動靜脈瘻管有嘈音（bruit）表示有阻塞情形", "動靜脈瘻管術後1 週後才可開始握球運動", "動靜脈瘻管術後6～8 週才可使用於血液透析", "動靜脈瘻管術後3 個月才可開始提重物"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=115100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "115100-102-0203-041", "year": 115, "session": "第二次", "no": 41, "stem": "41 有關腎病症候群病人的護理指導，下列何者正確？", "options": ["採取低蛋白質及均衡熱量飲食", "補充含鈉食物以避免低血鈉", "使用利尿劑及限水以控制水腫", "鼓勵多下床活動以減輕腎臟負荷"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=115100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "115100-102-0203-042", "year": 115, "session": "第二次", "no": 42, "stem": "42 有關急性腎盂腎炎病人的敘述，下列何者錯誤？", "options": ["詢問病人是否有泌尿道結石、泌尿道感染和糖尿病的病史", "觀察有無肋骨脊柱角疼痛、發燒、頻尿、尿液混濁及尿臭味", "鼓勵按時服用抗生素、止痛劑和大量攝液，以改善疼痛和細菌感染", "為了解有無腎衰竭發生，需監測紅血球沉降率和C 反應蛋白數值"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=115100&c=102&s=0203&q=1", "status": "needs_visual_review"}], "2": [{"id": "106030-106-0503-045", "year": 106, "session": "第一次", "no": 45, "stem": "45 有關燒傷病人利尿期出現代謝性酸中毒之原因，下列何者錯誤？", "options": ["乳酸堆積", "組織釋放酸性物質", "重碳酸鹽增加", "局部用藥Sulfamylon 副作用"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106030-106-0503-056", "year": 106, "session": "第一次", "no": 56, "stem": "56 有關病人動脈血液氣體分析結果：pH 7.30、PaCO2 40 mmHg、HCO3 －18 mEq/L、PaO2 70 mmHg、 O2\n\n      Saturation 93%之判讀，下列何者正確？", "options": ["未代償之呼吸性酸中毒", "過度代償之呼吸性鹼中毒", "未代償之代謝性酸中毒", "過度代償之代謝性鹼中毒"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-070", "year": 106, "session": "第二次", "no": 70, "stem": "70 低血容積與脫水的病人會出現的臨床表徵，不包括下列何者？", "options": ["心跳過速", "脈搏消失或呈絲脈", "黏膜潮濕", "心智狀況改變"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-063", "year": 106, "session": "第二次", "no": 63, "stem": "63 有關造成高血鉀症發生之原因， 下列何者錯誤？", "options": ["胰島素分泌過多", "溶血", "組織嚴重感染", "代謝性酸中毒"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-065", "year": 106, "session": "第二次", "no": 65, "stem": "65 有關因過度換氣造成呼吸性鹼中毒之處置，下列何者正確？", "options": ["以紙袋包住口鼻重複呼吸數次", "給予呼吸器維持換氣", "注射NaHCO3", "給予HCl"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-070", "year": 107, "session": "第一次", "no": 70, "stem": "70 有關代謝性酸中毒造成之原因，下列何者錯誤？", "options": ["過度運動", "過度飢餓", "嚴重腹瀉", "嚴重嘔吐"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107110-106-0503-044", "year": 107, "session": "第二次", "no": 44, "stem": "44 有關腫瘤溶解症候群之敘述 ，下列何者正確？①高血鉀症 ②高血鈣症 ③要補充大量水分 ④使\n     用kayexalate 可降低鈉離子  ⑤allopurinol 可降尿酸", "options": ["①②③", "①③⑤", "②④⑤", "③④⑤"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107110-106-0503-058", "year": 107, "session": "第二次", "no": 58, "stem": "58 執行動脈血液氣體分析時，未將抽取之血液樣本放置冰水中會導致檢查值發生之改變，下列何者正確？", "options": ["PaO2 上升", "pH 上升", "PaCO2 上升", "不會有任何改變"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-056", "year": 108, "session": "第一次", "no": 56, "stem": "56 有關呼吸性酸中毒之敘述，下列何者正確？", "options": ["因換氣速率過快所造成", "易見於水楊酸中毒病人", "中樞神經系統受刺激，病人會有手腳麻刺感", "慢性阻塞性肺疾病病人吸入過多氧氣易導致"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-070", "year": 108, "session": "第一次", "no": 70, "stem": "70 下列何者最可能造成病人出現昏迷、呼吸快而深、血清有效滲透壓300 mOsm/kg、血糖值400 mg/dL\n  的臨床表徵？", "options": ["蘇莫吉效應（Somogyi effect）", "急性肝昏迷", "糖尿病性酮酸中毒", "高血糖高滲透壓狀態"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108110-106-0503-072", "year": 108, "session": "第二次", "no": 72, "stem": "72 有關代謝性酸中毒的症狀，下列何者正確？", "options": ["出汗、口乾", "頭痛、意識遲鈍", "呼吸速率變慢", "周邊血管收縮"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-063", "year": 109, "session": "第一次", "no": 63, "stem": "63 體液容積不足時之臨床表徵，下列何者正確？①口渴 ②體溫上升 ③尿比重下降 ④血比容積升高", "options": ["①③", "①④", "②③", "②④"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-071", "year": 109, "session": "第一次", "no": 71, "stem": "71 有關高血磷病人的護理指導，下列何者正確？①少吃堅果類與糙米飯 ②多補充維生素D ③監測\n  小便量與肝功能 ④注意下床活動安全 ⑤服用磷結合劑", "options": ["①②③", "①④⑤", "②③④", "③④⑤"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-056", "year": 109, "session": "第二次", "no": 56, "stem": "56 下列動脈血液氣體分析的報告，何者最能顯示慢性阻塞性肺疾病（COPD）病人的情況惡化？", "options": ["pH 7.30，PaCO2 60 mmHg，PaO2 70 mmHg，HCO3- 30 mEq/L", "pH 7.38，PaCO2 45 mmHg，PaO2 88 mmHg，HCO3- 24 mEq/L", "pH 7.40，PaCO2 40 mmHg，PaO2 94 mmHg，HCO3- 22 mEq/L", "pH 7.55，PaCO2 30 mmHg，PaO2 80 mmHg，HCO3- 26 mEq/L"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-073", "year": 109, "session": "第二次", "no": 73, "stem": "73 下列何者為高血糖高滲透壓狀態（HHS）病人出現脫水的最常見原因？", "options": ["噁心、嘔吐", "缺乏抗利尿激素", "腎臟無法濃縮尿液", "高血糖造成滲透壓性利尿"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-027", "year": 110, "session": "第二次", "no": 27, "stem": "27 有關高血壓病人服用Propranolol（Inderal）的護理指導，下列何者正確？①需確認病人有無氣喘\n  ②服藥前宜先檢查心跳次數 ③副作用有低血鈉 ④副作用會造成脫水", "options": ["①②", "①③", "②③", "②④"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-064", "year": 112, "session": "第一次", "no": 64, "stem": "64 王先生的動脈血液氣體分析判讀結果為未代償性呼吸性酸中毒，下列敘述何者正確？", "options": ["pH 7.27、PaCO2 50 mmHg、HCO3- 25 mmHg、PaO2 80 mmHg", "pH 7.30、PaCO2 52 mmHg、HCO3- 30 mmHg、PaO2 81 mmHg", "pH 7.39、PaCO2 48 mmHg、HCO3- 32 mmHg、PaO2 89 mmHg", "pH 7.37、PaCO2 47 mmHg、HCO3- 31 mmHg、PaO2 81 mmHg"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-073", "year": 112, "session": "第一次", "no": 73, "stem": "73 有關副甲狀腺功能低下之臨床表徵，下列何者正確？①嗜睡 ②高血鈣 ③骨質耗損加劇 ④白內\n\n  障 ⑤高血磷", "options": ["①③⑤", "①④⑤", "②③④", "②③⑤"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-078", "year": 112, "session": "第一次", "no": 78, "stem": "78 有關敗血症生理病理機轉之敘述，下列何者正確？①細菌感染引發腫瘤壞死因子活化產生微小血栓\n\n  ②微生物侵入人體造成微血管通透性增加、全身循環血量增加 ③全身代謝狀態升高造成細胞耗氧量\n\n  增加，但組織血流灌注降低，產生代謝性酸中毒 ④因心臟受刺激出現血壓上升，可能引發尿量增加", "options": ["①②", "①③", "②④", "③④"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112110-102-0203-066", "year": 112, "session": "第二次", "no": 66, "stem": "66 黃女士的動脈血液氣體分析結果為完全代償性代謝性酸中毒，下列敘述何者正確？", "options": ["pH 7.35、PaCO2 30 mmHg、HCO3- 20 mmHg、PaO2 81 mmHg", "pH 7.31、PaCO2 28 mmHg、HCO3- 19 mmHg、PaO2 80 mmHg", "pH 7.32、PaCO2 47 mmHg、HCO3- 23 mmHg、PaO2 82 mmHg", "pH 7.33、PaCO2 36 mmHg、HCO3- 18 mmHg、PaO2 83 mmHg"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112110&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112110-102-0203-078", "year": 112, "session": "第二次", "no": 78, "stem": "78 當車禍造成嚴重創傷的病人送到急診出現：脈搏124 次／分、呼吸32 次／分胸部起伏明顯，血壓\n\n    130/100 mmHg、皮膚溼且冰冷、尿量減少、呈現呼吸性鹼中毒情形，下列休克階段的分期，何者正\n\n  確？", "options": ["早期", "代償期", "進行期", "不可逆期"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112110&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112180-101-0103-019", "year": 112, "session": "第三次", "no": 19, "stem": "19  有關Dopamine 作用的敘述，下列何者正確？①2 μg/kg/min 會增加心肌的自動性，因此可減少心室節律障礙\n  ②可治療低血容量性休克 ③5～10 μg/kg/min 主要作用是增加腎血流量 ④大於10 μg/kg/min 作用是末梢\n  血管收縮", "options": ["①③", "①④", "②③", "②④"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "112180-101-0103-035", "year": 112, "session": "第三次", "no": 35, "stem": "35 病人的動脈血液氣體分析報告為pH 7.36，PaO2 88 mmHg，PaCO2 50 mmHg，HCO3- 25 mEq/L，下列措施\n  何者應為最優先？", "options": ["立即通知主治醫師", "為病人戴上氧氣鼻套管", "用脈衝式血氧測定儀測量", "協助病人翻身並鼓勵其深呼吸咳嗽"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "113100-102-0203-034", "year": 113, "session": "第二次", "no": 34, "stem": "34 王先生呼吸喘，動脈血液氣體分析報告為：pH 7.20、PaCO2 61 mmHg、PaO2 62 mmHg、HCO3-22 mEq/L，\n  此結果判讀，下列何者正確？", "options": ["呼吸性鹼中毒", "代謝性酸中毒", "代謝性鹼中毒", "呼吸性酸中毒"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "113180-101-0103-033", "year": 113, "session": "第三次", "no": 33, "stem": "33 有關病人的動脈血液氣體分析結果，下列何者應立即報告醫師？", "options": ["pH 7.34，PaO2 82 mmHg，PaCO2 40 mmHg，SaO2 97%", "pH 7.35，PaO2 85 mmHg，PaCO2 45 mmHg，SaO2 95%", "pH 7.46，PaO2 90 mmHg，PaCO2 32 mmHg，SaO2 98%", "pH 7.31，PaO2 91 mmHg，PaCO2 50 mmHg，SaO2 96%"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "114100-102-0203-032", "year": 114, "session": "第二次", "no": 32, "stem": "32 有關高血鈉之敘述，下列何者正確？①血鈉的濃度＞130 mEq/L ②導因之一為醛固酮過多症導致 ③尿比重\n  上升 ④指導低鈉飲食如蘇打餅乾、白麵包", "options": ["①②", "①④", "②③", "③④"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "114100-102-0203-041", "year": 114, "session": "第二次", "no": 41, "stem": "41 高小姐的動脈血液氣體分析結果為pH 7.48、PaCO2 48 mmHg、HCO3- 30 mmHg、PaO2 92 mmHg，根據以\n\n  上數值，判讀結果下列何者正確？", "options": ["未代償性呼吸性酸中毒", "完全代償性代謝性酸中毒", "部分代償性代謝性鹼中毒", "未代償性呼吸性鹼中毒"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114100&c=102&s=0203&q=1", "status": "needs_visual_review"}], "3": [{"id": "106030-106-0503-059", "year": 106, "session": "第一次", "no": 59, "stem": "59  林先生，30 歲，無特殊疾病，因發燒、小便混濁及急性後背腰痛到急診，發現有尿道感染及輸尿管\n\n   結石0.5 cm，有關此急性期之護理措施，下列何者錯誤？", "options": ["等培養出細菌種類後再用特定的抗生素", "屬突發性、尖銳的疼痛應依醫囑使用止痛劑緩解疼痛", "可依醫囑使用平滑肌鬆弛劑緩解輸尿管痙攣", "鼓勵多喝水以利結石排出"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106030-106-0503-060", "year": 106, "session": "第一次", "no": 60, "stem": "60 有關女性尿道炎發生原因之機率，下列何者最低？", "options": ["化學物刺激", "雌激素減少", "淋病雙球菌感染", "克雷氏桿菌感染"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106030-106-0503-062", "year": 106, "session": "第一次", "no": 62, "stem": "62 趙小姐有長期反覆性尿道感染的病史，健檢時發現有鹿角結石約5 cm，下列敘述何者錯誤？", "options": ["是一種感染性結石", "可利用體外震波碎石術碎石", "限制高磷酸食物及碳酸飲料", "酸化尿液是預防此類結石復發的方法之一"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106030-106-0503-063", "year": 106, "session": "第一次", "no": 63, "stem": "63 王先生兩星期前因喉頭發炎、發燒就醫，近日出現血尿再次就醫，發現尿液中出現RBC、WBC、蛋\n\n  白質及圓柱體；血中BUN 及肌酸酐值上升。下列何者為其最可能之診斷？", "options": ["膀胱炎", "良性攝護腺肥大", "腎絲球腎炎", "腎病症候群\n代號：3106\n頁次：8－7"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106030-106-0503-066", "year": 106, "session": "第一次", "no": 66, "stem": "66 關於膀胱癌的敘述，下列何者錯誤？", "options": ["與長期暴露於抽菸的環境有關", "與大量使用止痛劑（Phenacetin）有關", "初期會有疼痛性血尿", "通常藉膀胱鏡檢查（Cystoscopy）來診斷"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-059", "year": 106, "session": "第二次", "no": 59, "stem": "59 下列何種藥物可以直接灌注於膀胱內以治療膀胱癌？", "options": ["BCG", "cisplatin", "methotrexate", "vinblastine"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-060", "year": 106, "session": "第二次", "no": 60, "stem": "60 與尿液pH 值無關之尿路結石成分，下列何者正確？", "options": ["尿酸", "磷酸鈣", "草酸鈣", "胱胺酸"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-062", "year": 106, "session": "第二次", "no": 62, "stem": "62 正常成年人，若膀胱容積壓力正常，最大尿流速低於下列何者即顯示尿道出口有阻塞現象？", "options": ["40 mL/秒", "30 mL/秒", "20 mL/秒", "10 mL/秒"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-004", "year": 106, "session": "第二次", "no": 4, "stem": "4 有關脊髓損傷所引起神經性膀胱的敘述，下列何者正確？", "options": ["肛門反射及肛門外括約肌張力試驗呈陽性反應，表示S2～S4 排尿反射中樞完整", "下運動神經元神經性膀胱訓練時，應教導病人引發反射性排尿的方法", "上運動神經元神經性膀胱訓練時，應教導病人以Crede's method 刺激排尿", "進行膀胱訓練時，當自解尿量：餘尿量＝2：1 且餘尿量＜150 mL 表示訓練成功"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-033", "year": 106, "session": "第二次", "no": 33, "stem": "33 有關癌症與腫瘤標記間的關係，下列何者較具顯著性？①肝癌–CEA ②前列腺癌–PSA ③乳癌–AFB\n\n   ④鼻咽癌–EBV", "options": ["①②", "②③", "②④", "③④"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-059", "year": 106, "session": "第二次", "no": 59, "stem": "59 有關膀胱癌化學治療藥物，下列何者較不適宜經由靜脈靜注給予？", "options": ["Cisplatin", "Doxorubicin", "Thiotepa", "Vinblastine\n代號：3106\n頁次：8－7"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-061", "year": 106, "session": "第二次", "no": 61, "stem": "61 因前列腺肥大導致膀胱變化之敘述，下列何者錯誤？", "options": ["膀胱內小樑形成", "膀胱內結石形成", "假性憩室形成", "膀胱壁組織增厚"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-077", "year": 106, "session": "第二次", "no": 77, "stem": "77 承上題，入急診室後即給予留置導尿管，6 小時後，尿液檢查結果顯示細菌感染，測量生命徵象：\n\n   體溫38.5℃、心跳130 次／分鐘、呼吸35 次／分鐘、血壓為55/30 mmHg，無尿。下列何者為病人\n\n  最可能之診斷？", "options": ["全身性炎性反應症候群（SIRS）", "敗血症", "嚴重敗血症", "敗血性休克"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-006", "year": 107, "session": "第一次", "no": 6, "stem": "6 有關中風病人功能性尿失禁問題的敘述，下列何者正確？①建立讓病人有表達如廁需要的溝通方法\n\n  ②儘量包著尿布以避免因為失禁引起病人的困窘 ③應存放留置尿管以預防尿液滯留 ④白天每\n\n   2～3 小時協助病人如廁一次", "options": ["①③", "①④", "②③", "②④"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-059", "year": 107, "session": "第一次", "no": 59, "stem": "59 有關服用抗結核菌藥物（Rifampin）病人尿液之顏色，下列何者正確？", "options": ["綠色", "橙色", "黑褐色", "藍色\n代號：3106\n頁次：8－7"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-061", "year": 107, "session": "第一次", "no": 61, "stem": "61 有關應力性尿失禁的處置方式，下列何者的治療效益有限？", "options": ["藥物", "骨盆底肌肉運動", "生理回饋訓練", "生活型態修正"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107110-106-0503-063", "year": 107, "session": "第二次", "no": 63, "stem": "63 下列何者為確立無痛性血尿是否為膀胱癌之最佳診斷檢查？", "options": ["膀胱鏡暨切片", "尿液細胞學檢查", "核磁共振檢查", "靜脈腎盂攝影術"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107110-106-0503-064", "year": 107, "session": "第二次", "no": 64, "stem": "64 有關預防膀胱癌之護理指導，下列何者不適當？", "options": ["不抽菸並遠離二手菸", "不吃含防腐劑和化學添加劑的食物", "避免接觸染劑及有機溶劑", "每天服用維生素 E 及相關之抗氧化製劑"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107110-106-0503-065", "year": 107, "session": "第二次", "no": 65, "stem": "65 有關接受前列腺切除術病人之護理措施與指導，下列何者錯誤？", "options": ["手術前2 天採清淡低渣液體飲食", "放置三叉導尿管作為引流尿液及膀胱灌洗的通路", "以蒸餾水進行膀胱灌洗", "手術後第一天可能會出現鮮紅色尿液\n代號：3106\n頁次：6－6"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-004", "year": 108, "session": "第一次", "no": 4, "stem": "4 有關脊髓損傷所引起的神經性膀胱之敘述，下列何者正確？", "options": ["下運動神經元神經性膀胱之排尿反射中樞是完整的", "下運動神經元神經性膀胱訓練時可利用反射來排尿", "上運動神經元神經性膀胱病人可以敲恥骨上緣或刺激肛門以誘發排尿", "上運動神經元神經性膀胱的病人常發生腎臟合併症"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-060", "year": 108, "session": "第一次", "no": 60, "stem": "60 膀胱癌的初期臨床表徵，下列何者正確？", "options": ["體重減輕", "頻尿", "無痛性血尿", "食慾不振"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-061", "year": 108, "session": "第一次", "no": 61, "stem": "61 下列何者是男性較常出現的尿失禁型態？", "options": ["應力型", "急迫型", "滿溢型", "功能性"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-007", "year": 109, "session": "第一次", "no": 7, "stem": "7 有關脊髓損傷造成弛緩型神經性膀胱的排尿訓練，下列何者正確？", "options": ["定時敲擊恥骨上方，以刺激排尿反射", "使用副交感神經刺激劑，以利膀胱迫尿肌收縮", "練習會陰肌肉收縮運動", "尿管留置或尿布使用，以解決滲尿問題"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-018", "year": 109, "session": "第一次", "no": 18, "stem": "18 有關脂肪栓塞症之症狀和徵象，下列何者正確？①呼吸急促 ②意識混亂 ③排尿增加 ④體溫上升", "options": ["①②③", "①②④", "①③④", "②③④"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-061", "year": 109, "session": "第一次", "no": 61, "stem": "61 有關尿液檢查的敘述，下列何者錯誤？", "options": ["尿液分析是泌尿系統最簡便的例行檢查", "細菌培養若細菌數＞105 CFU/c.c.表示泌尿道感染", "尿中肌酸酐和尿素氮是評估腎功能最佳指標", "清晨第一次尿液是尿液分析時最佳檢體"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-060", "year": 109, "session": "第二次", "no": 60, "stem": "60 有關膀胱癌的敘述，下列何者錯誤？", "options": ["初期最常見的症狀是無痛性間歇或持續血尿", "好發於膀胱外側壁、膀胱三角，以泌尿上皮癌最多", "橡膠製造業、美髮業與吸菸者都是高危險族群", "以腎臟與淋巴轉移最為常見，主要轉移到胸腔淋巴結"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-061", "year": 109, "session": "第二次", "no": 61, "stem": "61 有關壓力性尿失禁的治療與照護，下列何者錯誤？", "options": ["肥胖者要接受飲食療法來適當減輕體重，以減少腹壓", "透過骨盆底肌肉運動強化肌肉功能，協助關閉尿道口", "限制每天水分攝取量並配合排尿計畫，執行膀胱訓練", "使用α-腎上腺致效劑，增加尿道出口阻力"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-064", "year": 109, "session": "第二次", "no": 64, "stem": "64 關於膀胱癌接受膀胱切除及輸尿管造瘻術術後病人之護理措施，下列何者不適當？", "options": ["教導病人及照顧者觀察造瘻口之顏色、大小、形狀", "集尿袋尿液達80%才需排空", "鼓勵每日攝取液體2,000～3,000 mL", "鼓勵病人表達感受，傾聽病人給予心理支持"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-062", "year": 110, "session": "第一次", "no": 62, "stem": "62 有關尿液檢查目的之敘述，下列何者正確？", "options": ["尿液細菌培養是泌尿道疾病初步常規檢查", "24 小時尿液檢查可以評估尿中蛋白質含量", "酚紅試驗是測定腎絲球對外排除的能力", "肌酸酐廓清率是檢驗腎小管尿液濃縮的能力"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-063", "year": 110, "session": "第一次", "no": 63, "stem": "63 泌尿道結石成分為尿酸時之處置與照護，下列何者正確？", "options": ["可使用Probencid 降低血中尿酸值，避免復發", "攝取鹼性食物（如肉類、乾梅或穀類等），促使尿液鹼化", "避免攝取香菇、豆類、海鮮與內臟等，減少尿酸形成", "需維持每日尿量，可多飲用開水、茶或啤酒等，增加尿量"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-064", "year": 110, "session": "第一次", "no": 64, "stem": "64 有關膀胱癌的診斷檢查與治療，下列何者錯誤？", "options": ["尿液細胞學檢查是確認惡性細胞最方便的方式", "以化學治療與放射線治療為主，外科切除為輔", "膀胱鏡檢查是確診和定期追蹤的主要方式", "膀胱化學灌藥適用於未侵犯肌肉表淺性腫瘤"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-066", "year": 110, "session": "第一次", "no": 66, "stem": "66 有關接受經尿道前列腺切除術病人之護理指導，下列何者錯誤？", "options": ["逆行性射精為術後常見暫時性的問題", "3 個月內應避免騎腳踏車或跑步", "避免上樓梯，以免因腹內壓增加而出血", "避免坐浴或熱敷下腹部，以減少出血機會"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-067", "year": 110, "session": "第一次", "no": 67, "stem": "67 有關良性前列腺肥大的合併症，下列何者錯誤？", "options": ["尿毒症", "膀胱結石", "壓力性尿失禁", "尿道炎"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-002", "year": 110, "session": "第二次", "no": 2, "stem": "2 有關S2～S4 完全性脊髓損傷後排尿功能之敘述，下列何者正確？", "options": ["可藉由排尿反射排空膀胱", "屬溢尿性神經性膀胱", "膀胱容量很小", "屬於上運動神經元神經性膀胱"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-062", "year": 110, "session": "第二次", "no": 62, "stem": "62 有關膀胱癌進行尿路改道手術後之照護，下列何者正確？", "options": ["鼓勵多進食酸性食物，以酸化尿液可預防感染", "造瘻口周圍皮膚結晶物可用稀釋碳酸氫鈉清除", "需控制每日水分攝取量，以避免產生尿液滲漏", "造瘻口應為暗紅色、乾燥，出現黏性分泌物需返診"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-063", "year": 110, "session": "第二次", "no": 63, "stem": "63 下列何者於檢查後，不會出現血尿情況？", "options": ["膀胱鏡", "腎臟切片", "尿流速", "逆行性腎盂攝影術"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-064", "year": 110, "session": "第二次", "no": 64, "stem": "64 下列何種疾病的常見臨床症狀不包括血尿？", "options": ["輸尿管結石", "腎絲球腎炎", "前列腺肥大", "膀胱癌\n代號：3104\n頁次：6－6"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-065", "year": 110, "session": "第二次", "no": 65, "stem": "65 有關急迫性尿失禁的護理措施，下列何者最不適當？", "options": ["需減重與避免增加腹壓的活動，如提重物", "避免食用刺激膀胱的食物如咖啡、茶或酒", "指導凱格爾運動來訓練強化骨盆底肌肉", "協助擬訂排尿計畫作膀胱訓練增加容量"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111030-104-0303-043", "year": 111, "session": "第一次", "no": 43, "stem": "43 有關前列腺癌之敘述，下列何者正確？", "options": ["藥物治療大多使用雄性素", "放射線治療時最常使用鈷60 放射源", "鹼性磷酸酶值過高與前列腺癌之診斷有關", "前列腺特異性抗原（PSA）濃度可做為治療效果的參考"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111030-104-0303-068", "year": 111, "session": "第一次", "no": 68, "stem": "68 有關經尿道前列腺切除術的敘述，下列何者錯誤？", "options": ["透過電刀切除前列腺，是良性前列腺肥大第一線最常用的治療方式", "若手術過程吸收過多沖洗液，容易引起腦水腫需注意病人意識狀態", "出血是最常見的合併症，術後需要持續用生理食鹽水做膀胱灌洗", "若尿道內括約肌有受損，可能導致性行為高潮時出現逆行性射精"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-062", "year": 111, "session": "第二次", "no": 62, "stem": "62 有關膀胱結石的治療與照護措施，下列何者錯誤？", "options": ["建議使用體外震波碎石術治療，較不具侵入性", "結石成分為尿酸時，指導避免食用內臟、香菇等", "預防感染通常會先用廣效性抗生素", "術後鼓勵多喝水並監測輸出入量與尿液顏色、氣味等"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-063", "year": 111, "session": "第二次", "no": 63, "stem": "63 有關前列腺肥大與前列腺癌的敘述，下列何者錯誤？", "options": ["排尿困難、頻尿與尿瀦留等是常見症狀", "前列腺癌與雄性素有關，好發於前列腺中葉", "前列腺肥大經常會合併膀胱結石、尿路感染", "直腸指診和前列腺特異抗原是篩檢的診斷方法"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-067", "year": 111, "session": "第二次", "no": 67, "stem": "67 下列何者可能出現膀胱容量增加？", "options": ["膀胱發炎", "膀胱纖維化", "上運動神經元受損", "慢性膀胱出口阻塞"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-059", "year": 112, "session": "第一次", "no": 59, "stem": "59 有關膀胱炎之敘述，下列何者最適宜？", "options": ["尿液檢驗值每毫升尿液菌數大於105 個表示正常", "服用抗生素Neomycin，可給與維生素C 酸化尿液", "反覆性泌尿道感染須連續使用3～5 天抗生素", "指導病人每天攝取至少3,000 c.c.以上液體"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-060", "year": 112, "session": "第一次", "no": 60, "stem": "60 有關泌尿道感染病人應多攝取之酸灰性食物，下列何者錯誤？", "options": ["肉類、蛋", "燕麥、玉米", "梅子、李子", "牛奶、柑橘"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-062", "year": 112, "session": "第一次", "no": 62, "stem": "62 有關逆行性腎盂造影術之敘述，下列何者正確？①檢查前評估病人有無鋇劑過敏病史 ②檢查前衛\n\n  教病人勿排空膀胱 ③此檢查使用的顯影劑不會進入血流 ④檢查後監測病人有無尿瀦留、感染、\n\n  血尿情形", "options": ["①②", "①④", "②③", "③④"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-065", "year": 112, "session": "第一次", "no": 65, "stem": "65 有關輸尿管結石常見之臨床症狀，下列何者錯誤？", "options": ["腰部、會陰疼痛", "噁心、嘔吐", "頻尿、尿急", "寒顫、發燒"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112110-102-0203-060", "year": 112, "session": "第二次", "no": 60, "stem": "60 有關前列腺癌之敘述，下列何者錯誤？", "options": ["排尿困難、頻尿、血尿與尿瀦留是常見的症狀", "直腸指診和前列腺特異抗原是篩檢的診斷方法", "轉移時最常出現背痛、腰痛、血鈣異常", "前列腺癌與雄性素有關，好發於前列腺的中葉"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112110&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112110-102-0203-063", "year": 112, "session": "第二次", "no": 63, "stem": "63 有關急迫性尿失禁之照護，下列敘述何者正確？①可給予副交感神經藥物 ②指導膀胱訓練法 ③指\n\n  導病人使用尿失禁輔助用品如護墊或尿布 ④施行人工尿道括約肌植入術", "options": ["①②", "①④", "②③", "③④"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112110&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112110-102-0203-064", "year": 112, "session": "第二次", "no": 64, "stem": "64 下列何者會出現間歇性無痛血尿之症狀？①尿道炎 ②輸尿管結石 ③膀胱癌 ④腎臟癌", "options": ["①②", "①④", "②③", "③④"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112110&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112180-101-0103-001", "year": 112, "session": "第三次", "no": 1, "stem": "1 陳先生因車禍造成頸椎第5～6 節完全損傷，已度過脊髓休克期，目前進行膀胱訓練，下列敘述何者正確？\n  ①屬於痙攣型神經性膀胱 ②只要薦神經受到刺激，即會反射排尿 ③可以利用Crede’s method 以手握\n  拳，壓在膀胱，協助排空 ④當自解：餘尿量＝2：1，且餘尿小於100 mL 表示膀胱訓練成功", "options": ["①②", "①③", "②④", "③④"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "113100-102-0203-023", "year": 113, "session": "第二次", "no": 23, "stem": "23 有關常見腫瘤標記的應用，下列何者正確？①癌胚抗原（CEA）可監測結腸直腸癌治療效果 ②癌抗\n  原125（CA125）可監測胰臟癌與消化道腫瘤 ③前列腺特異抗原（PSA）為前列腺癌的偵測與治療指標\n  ④癌抗原15-3（CA15-3）可監測晚期或合併遠端轉移乳癌之治療反應 ⑤α-胎兒蛋白（AFP）為監測\n  肺癌治療後的指標", "options": ["①②⑤", "①③④", "②③④", "②③⑤"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "113100-102-0203-037", "year": 113, "session": "第二次", "no": 37, "stem": "37 有關良性前列腺肥大症狀與導因之敘述，下列何者正確？", "options": ["增生後期代償現象會出現頻尿、夜尿等症狀", "膀胱出口阻塞導致反覆感染，造成膀胱壁增厚", "逼尿肌長期壓力上升，產生膀胱內假性憩室", "尿道受壓造成內括約肌鬆弛，故尿流速變慢"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "113100-102-0203-039", "year": 113, "session": "第二次", "no": 39, "stem": "39 有關尿失禁照護之敘述，下列何者正確？①凱格爾式運動可改善壓力性尿失禁 ②定時導尿法可改善滿溢\n  性尿失禁 ③長期導尿管留置可改善急迫性尿失禁 ④膀胱訓練可改善完全性尿失禁", "options": ["①②", "①③", "②④", "③④"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "113100-102-0203-040", "year": 113, "session": "第二次", "no": 40, "stem": "40 王先生，85 歲，因排尿燒灼感、疼痛且出現膿尿、血尿至急診求治，生命徵象正常，有關其進一步之評估\n  與檢查，下列何者錯誤？", "options": ["年紀大可能前列腺肥大而出現排尿問題，需進行肛門指診檢查", "需協助收集尿液常規與細菌培養，以確認病因、菌種與用藥方向", "體溫正常即可排除感染，可能年紀大飲水不足而導致尿液性狀改變", "尿液細菌培養若每毫升含有105 個以上菌落，可確認是泌尿道感染"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "113180-101-0103-023", "year": 113, "session": "第三次", "no": 23, "stem": "23 有關體液容積過量之檢驗結果，下列敘述何者正確？①血比容下降 ②血尿素氮下降 ③血漿滲透壓上升\n  ④血鈉上升", "options": ["①②", "①③", "②④", "③④\n代號：3101\n頁次：4－3"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "113180-101-0103-040", "year": 113, "session": "第三次", "no": 40, "stem": "40 有關良性前列腺肥大之症狀與導因，下列何者正確？", "options": ["頻尿和夜尿等膀胱儲存症狀，為增生最早出現的現象", "長期尿道阻力降低造成逼尿肌代償，產生膀胱憩室", "增生壓迫尿道造成內括約肌鬆弛，引起尿流速變慢", "膀胱出口阻塞導致膀胱反覆感染，造成膀胱壁增厚"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "114100-102-0203-037", "year": 114, "session": "第二次", "no": 37, "stem": "37 有關尿液檢查之敘述，下列何者錯誤？", "options": ["除了早晨第一次尿外，任何時間採集的尿液稱之為隨機尿", "導尿管留置可由蓄尿袋採尿送檢查", "尿液檢體應於30 分鐘內送檢查為宜", "常規尿液收集是要取中段尿送檢查\n代號：3102\n頁次：4－4"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "114100-102-0203-040", "year": 114, "session": "第二次", "no": 40, "stem": "40 有關泌尿道感染及衛教之敘述，下列何者最適當？", "options": ["建議食用鹼化尿液的食物如柑橘及奶製品", "女性病人最常見的感染源為陰道滴蟲感染", "泌尿道感染病人的典型症狀為無痛性血尿", "院內泌尿道感染常見於泌尿道侵入性檢查後"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "114170-101-0103-049", "year": 114, "session": "第三次", "no": 49, "stem": "49 有關泌尿道感染，下列敘述何者最適當？①確立診斷是指尿液培養每毫升菌落>105 個 ②上泌尿道感染是\n\n  指尿道炎及膀胱炎 ③膀胱炎常見的致病菌為大腸桿菌 ④症狀改善或沒發燒即可停用抗生素", "options": ["①②", "①③", "②④", "③④"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114170&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "115100-102-0203-038", "year": 115, "session": "第二次", "no": 38, "stem": "38 有關良性前列腺肥大的敘述，下列何者正確？", "options": ["初期症狀首先出現逆行性射精", "晚期症狀出現滿溢型尿失禁", "直腸指診可準確診斷尿道阻塞的程度", "國際前列腺症狀量表（IPSS）總分7 分為嚴重症狀\n代號：3102\n頁次：4－4"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=115100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "115100-102-0203-040", "year": 115, "session": "第二次", "no": 40, "stem": "40 有關接受膀胱鏡檢查病人的護理指導，下列何者不適當？", "options": ["若採局部麻醉，檢查前必須禁食", "檢查過程中要保持不動，以避免泌尿道黏膜損傷", "檢查後請病人觀察有無腹部劇痛、血塊和排尿困難的情形", "檢查後請病人多喝水，以減輕排尿灼熱感和稀釋尿液"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=115100&c=102&s=0203&q=1", "status": "needs_visual_review"}], "4": [{"id": "106030-106-0503-005", "year": 106, "session": "第一次", "no": 5, "stem": "5 陳小姐診斷為腦下垂體腫瘤，進行經蝶骨腦下垂體切除術，術後出現尿崩症，下列敘述何者錯誤？", "options": ["尿的顏色很淡", "尿比重< 1.005", "血清鈉（Na+）< 125 mEq/L", "若不治療則會出現脫水的症狀"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106030-106-0503-024", "year": 106, "session": "第一次", "no": 24, "stem": "24  使用Beta 腎上腺素阻斷劑治療青光眼之敘述，下列何者錯誤？", "options": ["可以縮小瞳孔", "可以減少房水液的生成", "氣喘病人禁止使用", "給藥前需評估是否有心搏徐緩"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106030-106-0503-040", "year": 106, "session": "第一次", "no": 40, "stem": "40 有關腫瘤病人出現抗利尿激素分泌失調症候群之護理措施，下列何者錯誤？", "options": ["鼓勵增加水分攝取", "評估意識程度", "監測尿液滲透壓", "監測血中鈉離子濃度"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106030-106-0503-061", "year": 106, "session": "第一次", "no": 61, "stem": "61 接受根除性腎臟切除術之病人，術後24～48 小時需監測有無腎上腺功能不足之症狀，下列何者錯誤？", "options": ["尿量減少", "高血鈉", "低血壓", "意識程度改變"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106030-106-0503-067", "year": 106, "session": "第一次", "no": 67, "stem": "67 有關甲狀腺風暴的臨床表徵，下列何者正確？", "options": ["T3、T4 下降", "體溫過高、譫妄", "游離甲狀腺素下降", "心搏過慢、臉部潮紅"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106030-106-0503-069", "year": 106, "session": "第一次", "no": 69, "stem": "69 有關糖尿病病人飲食控制原則之敘述，下列何者正確？", "options": ["膽固醇每日攝取量低於300 mg", "蛋白質需求量占每日總熱量的20%～30%", "脂肪需求量占每日總熱量的50%", "碳水化合物占每日總熱量的30%～40%"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106030-106-0503-070", "year": 106, "session": "第一次", "no": 70, "stem": "70 有關糖尿病酮酸中毒之常見徵象，下列何者正確？", "options": ["皮膚濕冷或出汗", "呼吸性酸中毒", "出現Kussmaul’s 呼吸", "症狀發展非常快速"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106030-106-0503-071", "year": 106, "session": "第一次", "no": 71, "stem": "71 唐女士，口腔癌術後狀況穩定，胰島素注射一天4 次，鼻胃管灌食一天6 餐，消化良好，空腹指尖血\n\n   糖約100～140 mg/dL，手術前糖化血色素（HbA1c）為9.5%。唐女士表示「我住院開刀前糖尿病是以\n\n  口服藥控制，而且血糖控制很好的，我一定要注射胰島素嗎？」護理師的回答，下列何者最適切？", "options": ["「一旦開始注射胰島素，就終生需注射胰島素，沒關係，我們會教您的！」", "「您手術前的糖化血色素是9.5%，血糖控制很差喔！打針比較好。」", "「目前胰島素注射對您的病情及血糖控制是有幫助的，您擔心的是什麼？」", "「您很怕打針是嗎？現在血糖控制還不錯，我會請醫師幫您調整藥物。」"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106030-106-0503-072", "year": 106, "session": "第一次", "no": 72, "stem": "72 有關甲狀腺機能亢進之護理指導，下列何者錯誤？", "options": ["依醫囑服用飽和碘化鉀溶液，可以抑制甲狀腺素的合成", "依醫囑服用飽和碘化鉀溶液，絕不可與果汁一起服用", "甲狀腺切除手術後一週內應評估病人有無Chvostek’s 及Trousseau’s 徵象", "病人易出現多汗，應提供舒適而清涼的環境\n代號：3106\n頁次：8－8"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-065", "year": 106, "session": "第二次", "no": 65, "stem": "65 有關甲狀腺機能亢進病人服用碘製劑之注意事項，下列何者正確？", "options": ["水溶性碘應貯存於紙杯", "應以吸管飲用，避免牙齒染色", "服用放射性碘後，應限制飲水", "不可與牛奶或果汁混合飲用\n代號：3106\n頁次：6－6"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-067", "year": 106, "session": "第二次", "no": 67, "stem": "67 有關第2 型糖尿病之敘述，下列何者正確？", "options": ["多發生於成年期", "發病與自體免疫有關", "需終生依賴胰島素治療", "因胰島素接受器增加所造成"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-068", "year": 106, "session": "第二次", "no": 68, "stem": "68 有關腦下垂體前葉分泌之激素，不包括下列何者？", "options": ["生長素", "促乳素", "催產素", "黃體促素"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-071", "year": 106, "session": "第二次", "no": 71, "stem": "71 有關尿崩症病人的出院護理指導，下列何者不適當？", "options": ["教導自我注射藥物的方法", "告知隨身攜帶識別卡", "教導維持與測量體液狀態的方式", "教導使用鼻噴霧劑，並須確認藥劑確實吸入肺部"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-005", "year": 106, "session": "第二次", "no": 5, "stem": "5 頭部外傷病人手術後出現抗利尿激素分泌失調之敘述，下列何者正確？", "options": ["抗利尿激素分泌不當症候群（SIADH）是因抗利尿激素分泌減少", "尿崩症是因抗利尿激素分泌太多", "出現尿崩症時應每小時監測I/O、尿比重、尿液的顏色", "出現尿崩症時應注意有無低血鈉造成嗜睡的中樞神經症狀"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-021", "year": 106, "session": "第二次", "no": 21, "stem": "21 有關糖尿病視網膜病變之敘述，下列何者錯誤？", "options": ["會造成病人失明", "與血糖控制不良無關", "視網膜血管損傷或阻塞", "可能導致牽引性視網膜剝離\n代號：3106\n頁次：8－3"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-064", "year": 106, "session": "第二次", "no": 64, "stem": "64 糖尿病腎病變初期為微量蛋白尿期，於此期每日尿液排出之白蛋白量，下列何者正確？", "options": ["≦30 mg", "31～300 mg", "301～500 mg", "≧500 mg"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-067", "year": 106, "session": "第二次", "no": 67, "stem": "67 有關甲狀腺機能亢進的臨床表徵，下列何者正確？", "options": ["食慾下降", "心跳過速", "腸蠕動減慢", "三碘甲狀腺素下降"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-069", "year": 106, "session": "第二次", "no": 69, "stem": "69 預防甲狀腺切除後傷口縫合處過度牽扯及減輕傷口腫脹不適之姿勢，下列何者正確？", "options": ["俯臥，頭部轉向側邊", "仰臥，頭頸下墊枕頭支撐", "側臥，頭頸下墊枕頭支撐", "半坐臥，頭頸部以枕頭支托固定"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-070", "year": 106, "session": "第二次", "no": 70, "stem": "70 有關愛迪生氏危機出現的症狀，下列何者正確？①高血鉀 ②高血壓 ③高血糖 ④低血容積\n\n  ⑤體溫降低 ⑥痙攣", "options": ["①②③", "①④⑥", "②④⑤", "③⑤⑥"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-072", "year": 106, "session": "第二次", "no": 72, "stem": "72 有關庫欣氏症候群症狀之病理機轉，下列何者錯誤？", "options": ["肌肉無力：蛋白質過度分解、造成肌肉質塊流失", "水腫：礦物皮質醇活化，導致水分與鈉離子滯留", "傷口癒合慢：皮質醇分泌上升，造成淋巴球下降", "低血糖：肝臟糖質新生作用降低，胰島素利用增加\n代號：3106\n頁次：8－8"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-073", "year": 106, "session": "第二次", "no": 73, "stem": "73 有關嗜鉻細胞瘤切除手術後之護理措施，下列何者錯誤？", "options": ["注意高血壓症狀，必要時使用α 阻斷劑", "監測每小時小便量，小於30 c.c.／小時為異常", "觀察術後出血情況與腸蠕動狀態", "依醫囑給予靜脈輸液，以維持體液容積"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-074", "year": 106, "session": "第二次", "no": 74, "stem": "74 有關抗利尿激素分泌不當症候群（SIADH）之敘述，下列何者正確?", "options": ["體液容積擴大、體液高張、尿比重降低，而出現水中毒症狀", "補充高張氯化鈉溶液，以矯正低血鈉症狀", "症狀往往是慢慢出現，最常出現的是食慾增加與口渴", "病人需採頭低腳高之臥姿，以促進下肢體液回流"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-067", "year": 107, "session": "第一次", "no": 67, "stem": "67 有關副甲狀腺機能亢進病人之臨床表徵，下列何者正確？①便祕 ②低血鈣 ③骨質疏鬆 ④心律\n\n  不整 ⑤高血磷", "options": ["①②③", "①③④", "②④⑤", "③④⑤"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-068", "year": 107, "session": "第一次", "no": 68, "stem": "68 有關糖尿病性酮酸中毒病人的臨床表徵，下列何者正確？", "options": ["高血壓", "呼吸慢且淺", "代謝性鹼中毒", "症狀初期尿量增多"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-069", "year": 107, "session": "第一次", "no": 69, "stem": "69 有關服用甲狀腺素之敘述，下列何者正確？", "options": ["會降低毛地黃的效應", "會增加抗凝血劑的效應", "新生兒儘早採低劑量治療", "心絞痛病人應由大劑量開始使用"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-071", "year": 107, "session": "第一次", "no": 71, "stem": "71 有關嗜鉻細胞瘤典型之5P 症狀，不包括下列何者？", "options": ["高血壓", "高血鉀", "疼痛", "心悸\n代號：3106\n頁次：8－8"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-072", "year": 107, "session": "第一次", "no": 72, "stem": "72 有關尿崩症病人之照護與處置，下列何者不適當？", "options": ["腎原性尿崩症可透過限制飲食鹽分攝取，以緩解症狀", "使用鼻噴劑型DDAVP（Desmopressin）是補充抗利尿素最佳給藥途徑", "限制每日水分攝取量，可避免出現代償性體液調節作用", "需要密集監測生命徵象、每日體重變化、尿比重、電解質"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107110-106-0503-069", "year": 107, "session": "第二次", "no": 69, "stem": "69 有關皮下注射胰島素吸收速率之比較，下列何者正確？", "options": ["大腿 > 臀部 >上臂 > 腹部", "運動肢體 > 非運動肢體", "注射處不動 > 注射處局部活動", "體溫下降 > 體溫升高"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107110-106-0503-070", "year": 107, "session": "第二次", "no": 70, "stem": "70  有關使用抗甲狀腺硫醯胺類（thionamides）藥物之敘述，下列何者正確？", "options": ["一般先用大劑量再逐漸減量", "症狀消失後即可停藥", "通常效果須等 2～3 個月後才顯現出來", "副作用易導致顆粒性白血球增多"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107110-106-0503-072", "year": 107, "session": "第二次", "no": 72, "stem": "72 有關糖尿病人足部照護之敘述，下列何者正確？", "options": ["可用刀片自行切除腳部硬繭或雞眼", "可用浮石輕輕將硬繭或雞眼磨光", "修剪指甲，需剪成直線型並在腳趾邊緣挖皮", "洗澡前先以前臂或手肘測試水溫"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107110-106-0503-075", "year": 107, "session": "第二次", "no": 75, "stem": "75 有關甲狀腺機能亢進症之臨床表徵，下列何者錯誤？", "options": ["眼球突出", "甲狀腺腫", "食慾不振", "心搏過速"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-067", "year": 108, "session": "第一次", "no": 67, "stem": "67 有關甲狀腺機能低下病人的臨床表徵，下列何者正確？", "options": ["低血鈉", "對熱敏感", "皮膚出現凹陷性水腫", "食慾降低且體重減輕"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-068", "year": 108, "session": "第一次", "no": 68, "stem": "68 有關糖尿病病人運動之護理指導，下列何者正確？", "options": ["胰島素作用高峰時，是最佳的運動時間", "腿部剛注射胰島素後，避免立即跑步運動", "運動方式儘量採急速變化，以達運動效果", "血糖超過300 mg/dL 時，應延長運動時間"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-069", "year": 108, "session": "第一次", "no": 69, "stem": "69 下列何者可評估糖尿病病人過去3 個月的血糖控制情形？", "options": ["空腹血糖值", "糖化血色素值", "口服葡萄糖耐受量", "飯後2 小時血糖值\n代號：3106\n頁次：6－6"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-071", "year": 108, "session": "第一次", "no": 71, "stem": "71 有關甲狀腺切除後可能發生的合併症，下列何者正確？", "options": ["高血鈣", "低血磷", "體溫過低", "喉返神經受損"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-072", "year": 108, "session": "第一次", "no": 72, "stem": "72 有關庫欣氏症候群的診斷檢查，下列何者最具特異性？", "options": ["24 小時尿液游離皮質醇排泄量", "核醫腎上腺皮質掃描", "標準二天類固醇抑制試驗", "蝶鞍核磁共振影像檢查"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-073", "year": 108, "session": "第一次", "no": 73, "stem": "73 有關剛接受腦下垂體切除術後病人的護理措施，下列何者錯誤？", "options": ["密切觀察有無低血容積與休克現象", "密切觀察有無顱內壓升高的症狀", "保持平躺，減少下肢靜脈回流，減輕頭痛現象", "密切觀察有無腦脊髓液外滲的情形"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-074", "year": 108, "session": "第一次", "no": 74, "stem": "74 有關抗利尿素分泌不當症候群（SIADH）病人的護理措施，下列何者錯誤？", "options": ["遵守與執行限制液體措施", "密切監測血壓、中心靜脈壓及血漿滲透壓的變化", "監測有無出現肌肉抽搐或昏迷等中樞神經傷害", "預防與高血鈉有關的潛在性傷害\n情況題：吳先生27 歲，因騎機車與卡車相撞造成左大腿骨折且有一長15 公分、深3 公分之撕裂傷，血流\n    不止，送達急診時，病人體溫36℃、心跳130 次／分、呼吸35 次／分、血壓90/60 mmHg，皮膚\n    冰冷潮濕，微血管充填時間大於5 秒。請依據上述資料回答第75 題至第77 題。"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108110-106-0503-067", "year": 108, "session": "第二次", "no": 67, "stem": "67 有關糖尿病酮酸中毒（DKA）之處置，下列何者錯誤？", "options": ["建立靜脈輸液，給予0.9%生理食鹽水", "皮下注射大劑量短效胰島素", "當血糖降至300 mg/dL，應補充葡萄糖溶液", "監測血中鉀離子濃度變化"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108110-106-0503-069", "year": 108, "session": "第二次", "no": 69, "stem": "69 有關甲狀腺切除後病人的護理措施，下列何者正確？①注意有無聲音嘶啞 ②禁止深呼吸、咳嗽運\n  動 ③喝溫開水減輕傷口不適 ④觀察口部刺麻感", "options": ["①②", "①④", "②③", "③④"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108110-106-0503-071", "year": 108, "session": "第二次", "no": 71, "stem": "71 有關副甲狀腺機能亢進病人之護理指導，下列何者正確？", "options": ["鼓勵攝取乳製品", "鼓勵攝取高鈣食物", "鼓勵攝取低纖維食物", "鼓勵攝取蔓越莓製品"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-062", "year": 109, "session": "第一次", "no": 62, "stem": "62  張先生，68 歲，罹患糖尿病、高血壓，冠心症長期服用降血糖藥物、抗凝血劑及高血壓藥物，但血\n   壓仍維持在150～170／90～110 mmHg。近日因血尿、下肢水腫、發燒而入院，住院期間病人不宜接\n  受下列何項診斷性檢查？", "options": ["靜脈腎盂攝影", "酚紅試驗", "肌酸酐廓清試驗", "腎臟活體組織切片"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-064", "year": 109, "session": "第一次", "no": 64, "stem": "64 甲狀腺機能亢進之臨床表徵，下列何者正確？①月經減少或停經 ②深肌腱反射減弱 ③指甲遠心\n  端鬆脫 ④皮膚潮紅乾裂 ⑤脛前黏液水腫 ⑥指尖有刺麻感", "options": ["①②③", "①③⑤", "②④⑥", "④⑤⑥"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-065", "year": 109, "session": "第一次", "no": 65, "stem": "65  長期使用類固醇製劑而導致愛迪生氏症（Addison’s disease）之病人所呈現的臨床表徵，下列何者\n  錯誤？", "options": ["皮膚與黏膜都會呈現褐色的色素沉著", "漸進性的疲累、軟弱無力及體重減輕", "出現眩暈等姿位性低血壓以及脫水徵象", "女性病人的腋毛與陰毛會出現減少情形"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-066", "year": 109, "session": "第一次", "no": 66, "stem": "66 有關高滲透壓高血糖狀態（HHS）之敘述，下列何者正確？", "options": ["血糖上升，但高血糖較酮酸中毒輕微", "血液pH 值下降，呈現酮酸中毒", "脫水嚴重，皮膚呈現潮紅、溫暖、乾燥", "出現庫斯莫爾氏呼吸（Kussmaul’s breathing）"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-067", "year": 109, "session": "第一次", "no": 67, "stem": "67 有關糖尿病的藥物治療之敘述，下列何者正確？", "options": ["metformin 為雙胍類（biguanides）抗血糖藥物，是治療糖尿病的首選藥物，肝腎功能異常者須慎用", "glipizide 為磺醯脲類（sulfonylureas）抗血糖藥物，與β 細胞磺醯脲類受體結合，刺激胰島素分泌，\n   應於飯後服用", "acarbose 為α 糖苷酶抑制劑（α-glucosidase inhibitors），在小腸抑制澱粉分解，延緩葡萄糖吸收，\n   應於飯前服用", "exenatide 為類升糖素肽受體促效劑（GLP-1 receptor agonists），促進GLP-1 的功能，刺激胰島素\n   分泌與抑制升糖素分泌，採肌肉注射\n代號：3106\n頁次：6－6"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-068", "year": 109, "session": "第一次", "no": 68, "stem": "68 有關糖尿病酮酸中毒（DKA）的敘述，下列何者正確？", "options": ["好發於女性老年人", "多發生在第1 型糖尿病病人胰島素治療中斷所致", "多發生於第2 型糖尿病病人身上，攝入過多食物所致", "可能因為胰島素過多，攝入過多食物所致"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-007", "year": 109, "session": "第二次", "no": 7, "stem": "7 王小姐進行經蝶骨腦下垂體切除術，術後發現鼻部有水樣液體流出之護理措施，下列何者正確？", "options": ["利用尿糖試紙檢視分泌物性質", "將病人的床頭抬高30 度", "用無菌的抽吸管吸乾淨", "用無菌棉球塞住鼻孔"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-019", "year": 109, "session": "第二次", "no": 19, "stem": "19 下列何者為退化性關節炎的高危險群？①BMI 35 kg/m2 ②長期服用腎上腺皮質類固醇 ③重複性右\n  膝受傷史 ④停經後婦女", "options": ["①②③", "①②④", "①③④", "②③④"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-068", "year": 109, "session": "第二次", "no": 68, "stem": "68 有關庫欣氏症候群症狀（Cushing’s syndrome）之病理機轉，下列何者正確？", "options": ["軀幹性肥胖：糖皮質素對脂肪和蛋白質代謝影響所導致", "高血壓：降低礦物皮質醇活化，導致水分與鈉離子滯留", "免疫受抑制：白血球增多，抑制單核球作用與淋巴球下降", "高血糖：肝臟糖質新生作用降低，胰島素利用增加所導致"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-070", "year": 109, "session": "第二次", "no": 70, "stem": "70 有關副甲狀腺功能低下病人之處置與護理，下列何者正確？", "options": ["急性期給予口服10% calcium gluconate", "手足抽搐時，注射重碳酸鹽或磷酸鹽，以迅速增加血鈣濃度", "床旁放置氣切包、氣管內管、喉頭鏡等物備用", "鼓勵攝取乳酪、奶類製品、蛋黃、花椰菜"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-072", "year": 109, "session": "第二次", "no": 72, "stem": "72 有關糖尿病的敘述，下列何者正確？", "options": ["第一型糖尿病病人體內會出現胰島細胞抗體（islet cell antibody；ICA）", "第一型糖尿病病人仍保有分泌胰島素能力，只是不足以供應身體所需", "第二型糖尿病易發生酮酸血症的急性合併症", "第二型糖尿病多發生於成年期，需終身依賴胰島素治療"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-075", "year": 109, "session": "第二次", "no": 75, "stem": "75 糖尿病病人在下列何種情況下不宜增加胰島素的劑量？", "options": ["全身感染", "食慾不振", "嚴重外傷", "情緒壓力"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-023", "year": 110, "session": "第一次", "no": 23, "stem": "23 關於糖尿病性酮酸中毒（DKA）的敘述，下列何者正確？", "options": ["屬於原發性呼吸性酸中毒", "易發生在第1 型糖尿病病人身上", "昏迷前常出現陳施氏呼吸", "急性期需及時補充葡萄糖來緩解症狀"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-068", "year": 110, "session": "第一次", "no": 68, "stem": "68  有關愛迪生氏危機（Addisonian crisis）之特徵，下列何者正確？", "options": ["高血壓", "高血糖", "低血鉀", "低血鈉"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-069", "year": 110, "session": "第一次", "no": 69, "stem": "69 有關嗜鉻細胞瘤的敘述，下列何者錯誤？", "options": ["因病人情緒激動導致腫瘤突然釋放大量兒茶酚胺所導致", "過量的腎上腺素與正腎上腺素會引起交感神經過度活動", "會出現5P 症狀：心悸、盜汗、疼痛、臉色蒼白及高血壓", "可透過檢測病人血液當中的杏仁酸（VMA）含量確立診斷"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-070", "year": 110, "session": "第一次", "no": 70, "stem": "70 有關糖尿病病人產生腎臟病變之敘述，下列何者正確？", "options": ["採高蛋白飲食可預防腎功能惡化", "是造成糖尿病病人最主要的死因", "只會出現在第2 型糖尿病病人", "因腎絲球基底膜變薄且通透性降低所造成"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-072", "year": 110, "session": "第一次", "no": 72, "stem": "72 有關糖尿病性酮酸中毒（DKA）治療之敘述，下列何者正確？", "options": ["處理低血糖", "矯正水分過度負荷狀態", "補充鈉離子", "矯正血液pH 值"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-073", "year": 110, "session": "第一次", "no": 73, "stem": "73 有關糖尿病足之護理指導，下列何者正確？", "options": ["足部保持乾燥，勿擦拭任何乳液", "足部要使用熱水袋或電毯保暖", "出門要穿涼鞋，以避免香港腳", "穿鞋前要先檢視鞋內有否異物"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-003", "year": 110, "session": "第二次", "no": 3, "stem": "3  腦下垂體腫瘤（pituitary tumor）病人出現雙顳側視野及視力變差，下列何者為其腫瘤壓迫部位？", "options": ["頂葉", "枕葉", "視交叉", "腦神經第III, IV, VI"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-060", "year": 110, "session": "第二次", "no": 60, "stem": "60 急性腎衰竭病人血清鉀為7.2 mEq/L，下列處置何者正確？①靜脈注射中長效胰島素及5%葡萄糖溶\n  液 ②口服或灌腸給予Kayexalate ③靜脈注射重碳酸鈉 ④鼓勵多食用香蕉、柳丁", "options": ["①③", "①④", "②③", "②④"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-068", "year": 110, "session": "第二次", "no": 68, "stem": "68 有關甲狀腺功能亢進病人的護理處置，下列何者正確？", "options": ["睡覺時採平躺，以利眼眶內液體回流，減少不適", "為預防角膜受傷，病人需限制飲食中的鉀含量", "教導病人需採高熱量、高蛋白與高纖維的飲食", "服用飽和碘化鉀溶液時，可混和牛奶一起服用"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-069", "year": 110, "session": "第二次", "no": 69, "stem": "69 有關甲狀腺素製劑使用原則與注意事項，下列何者錯誤？", "options": ["甲狀腺素製劑需終身服用，不可自行停藥或更改劑量", "甲狀腺素會增加毛地黃、Ketamine 及抗凝血劑藥物作用", "新生兒或嬰幼兒，應儘早採高劑量治療，以避免發育遲滯", "服用甲狀腺素製劑會使血糖下降，糖尿病病人需監測血糖"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-071", "year": 110, "session": "第二次", "no": 71, "stem": "71 有關蝶骨切除腦下垂體腫瘤的手術後護理處置，下列何者正確？", "options": ["不可用力擤鼻涕、打噴嚏、咳嗽、解便", "提醒Cortisone 類藥物，必須於飯前服用", "指導手術後二個月後，切勿進行彎腰動作", "若出現多尿、劇渴，表示可能血糖上升"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-072", "year": 110, "session": "第二次", "no": 72, "stem": "72 有關副甲狀腺機能亢進病人的臨床表徵，下列何者正確？①少尿 ②噁心 ③心律不整 ④骨鈣沉積", "options": ["①②", "①③", "②③", "②④"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-073", "year": 110, "session": "第二次", "no": 73, "stem": "73 王先生，58 歲，罹患糖尿病2 年，藉由口服抗血糖藥物、飲食與運動控制血糖，今日在家昏倒救護車\n  送入急診，心跳118 次／分，血壓85/50 mmHg，呼吸速率20 次／分，血糖為650 mg/dL。下列何者\n  為最可能之診斷？", "options": ["乳酸中毒", "低血糖昏迷", "糖尿病酮酸中毒（DKA）", "高滲透壓高血糖狀態（HHS）"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-075", "year": 110, "session": "第二次", "no": 75, "stem": "75 有關糖尿病視網膜病變的敘述，下列何者錯誤？", "options": ["視網膜眼底檢查可見微血管瘤，是屬於非增殖性視網膜病變", "區分增殖性或非增殖性視網膜病變可藉由直接觀察視網膜來確診", "視網膜新生血管破裂出血，液體從血管滲出，會造成黃斑部水腫", "糖尿病所引起的黃斑部病變可利用雷射治療恢復失去的視力"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111030-104-0303-063", "year": 111, "session": "第一次", "no": 63, "stem": "63  張先生50 歲，患有糖尿病腎病變，下列治療何項錯誤？", "options": ["鼓勵病人每天多攝取蛋白質（1.5～2.0 g/天）", "將糖化血色素控制在7%以內", "將血壓控制在130/80 mmHg 以內", "血管收縮素轉化酶抑制劑（ACEI）可用來控制血壓"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111030-104-0303-070", "year": 111, "session": "第一次", "no": 70, "stem": "70 有關抗利尿激素分泌不當症候群（SIADH）之臨床表徵，下列何者錯誤？", "options": ["通常是由泌尿道疾病引發", "最常出現症狀是食慾不振", "血鈉濃度會＜135 mEq/L", "病人會出現低尿酸血症"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111030-104-0303-071", "year": 111, "session": "第一次", "no": 71, "stem": "71 有關糖尿病病人足部護理，下列何者正確？①直線修剪趾甲緣 ②每日以溫水浸泡清洗足部30 分鐘\n  ③穿著色深、柔軟的尼龍襪，且每日更換 ④足部傷口沖洗後，消毒敷料覆蓋，紙膠固定，應儘速\n  就醫", "options": ["①②", "①④", "②③", "③④"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111030-104-0303-073", "year": 111, "session": "第一次", "no": 73, "stem": "73 有關甲狀腺功能低下症之護理措施，下列何者正確？", "options": ["服用甲狀腺素時採飯後使用，以避免胃酸增加", "使用甲狀腺素藥物時須監測血糖之變化", "給予病人電毯或熱水袋，以增加舒適及保暖", "鼓勵採高熱量、低纖維、低脂肪飲食"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111030-104-0303-074", "year": 111, "session": "第一次", "no": 74, "stem": "74 有關糖尿病酮酸中毒（DKA）與高滲透壓高血糖狀態（HHS）之臨床處置，下列何者正確？", "options": ["HHS 需補充的水分較少", "HHS 需要較多的胰島素治療", "HHS 較DKA 更需補充重碳酸鈉", "HHS 不需要補充鉀離子"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-004", "year": 111, "session": "第二次", "no": 4, "stem": "4 有關誘發腦下垂體中風原因的敘述，下列何者正確？", "options": ["導因於腫瘤壓迫於蝶鞍處，造成內部壓力上升", "導因於腫瘤壓迫於腦室，造成內部壓力上升", "導因於下視丘的顱內出血，造成內部壓力上升", "導因於近腦下垂體血管梗塞，造成內部壓力上升"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-016", "year": 111, "session": "第二次", "no": 16, "stem": "16 白老太太76 歲，有高血壓及糖尿病，配戴假牙，下列何者不是預防齲齒的護理指導？", "options": ["建議植牙", "使用牙線剔牙", "牙齒塗氟", "減少醣類攝取"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-068", "year": 111, "session": "第二次", "no": 68, "stem": "68 有關甲狀腺風暴的敘述，下列何者錯誤？", "options": ["病人臨床檢驗結果出現血中游離甲狀腺素（free T4）與TSH 上升", "評估病人是否出現發燒、心跳過速、脫水及暴躁不安之徵象", "依醫囑給予β-腎上腺素阻斷劑（Propranolol），以降低心搏速率", "依醫囑給予抑制甲狀腺素合成與釋放藥物，如：Methimazole (Tapazole)"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-069", "year": 111, "session": "第二次", "no": 69, "stem": "69 有關庫欣氏症候群（Cushing’s syndrome）的飲食指導，下列何者錯誤？", "options": ["高鈣", "高鉀", "低熱量", "低蛋白"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-070", "year": 111, "session": "第二次", "no": 70, "stem": "70 有關抗利尿激素分泌不當症候群（SIADH）的護理指導，下列何者錯誤？", "options": ["須限制液體，故每天液體攝入不超過500 mL", "向病人說明使用四環素主要目的是為了預防感染", "跟病人解釋頭部最好保持平躺，以防腦水腫", "教導病人攝取高纖、含鈉的食物，以改善便秘"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-071", "year": 111, "session": "第二次", "no": 71, "stem": "71 有關糖尿病酮酸中毒（DKA）病人的呼吸特徵，下列何者正確？", "options": ["深、快、有果香味", "淺、慢、有尿騷味", "深、慢、有果香味", "淺、快、有尿騷味"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-072", "year": 111, "session": "第二次", "no": 72, "stem": "72 有關高滲透壓高血糖狀態（HHS）的敘述，下列何者正確？", "options": ["好發於第一型糖尿病人", "呼吸加速且深度增加", "檢驗血中呈現無或微量酮體", "因無胰島素分泌導致高血糖"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-073", "year": 111, "session": "第二次", "no": 73, "stem": "73 有關甲狀腺功能亢進病人的飲食指導，下列何者正確？", "options": ["低蛋白飲食", "高碳水化合物飲食", "低熱量飲食", "高纖維飲食"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-075", "year": 111, "session": "第二次", "no": 75, "stem": "75 下列何者在副甲狀腺功能低下病人會呈現陽性反應？", "options": ["黎明現象（dawn phenomenon）", "洛夫辛徵象（Rovsing’s sign）", "腔室症候群（compartment syndrome）", "沃斯特克氏徵象（Chvostek’s sign）"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-001", "year": 112, "session": "第一次", "no": 1, "stem": "1 罹患腦下垂體腫瘤病人，醫師建議使用伽馬刀療法，下列何者顯示病人已了解本項治療？", "options": ["治療時我的頭部會有一個切開傷口", "治療時我不會疼痛也不會流血", "治療後我的頭部會有留一條小型引流管", "治療後我的腦瘤會立即消失"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-004", "year": 112, "session": "第一次", "no": 4, "stem": "4 有關腦腫瘤病人術後發生尿崩症，下列敘述何者正確？", "options": ["尿比重會比正常人高", "會有尿量多、血漿滲透壓下降", "因抗利尿素（ADH）分泌不足所致", "可能有低血鈉導致抽搐症狀"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-063", "year": 112, "session": "第一次", "no": 63, "stem": "63 有關抗利尿激素分泌不當症候群（SIADH）病人之臨床表徵，下列何者錯誤？", "options": ["低血清鈉", "低尿量", "低血漿滲透壓", "低尿比重"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-067", "year": 112, "session": "第一次", "no": 67, "stem": "67 有關造成糖尿病病人血糖過低之促因，下列何者正確？", "options": ["Glipizide 服用過量", "健走運動時間減少", "近期工作壓力增加", "近日上呼吸道感染"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-070", "year": 112, "session": "第一次", "no": 70, "stem": "70  陳小姐因甲狀腺機能亢進，接受抗甲狀腺藥物硫醯胺類（thioamides）與碘製劑（iodine）治療，有關\n\n  其藥物治療之敘述，下列何者正確？", "options": ["給與大劑量硫醯胺類藥物，隨著血清T3 和T4 數值降低而減量，待正常就可以停藥", "碘製劑有顆粒球與血小板減少的副作用，第一次給藥前應先測白血球與血小板數目", "服用硫醯胺類藥物的目的是為了減少甲狀腺腺體的血管分布", "碘製劑使用不宜超過2 週，以免造成甲狀腺逸脫，使大量甲狀腺素進入循環加重症狀"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-071", "year": 112, "session": "第一次", "no": 71, "stem": "71 承上題，陳小姐近期藥物治療反應不佳而入院接受甲狀腺切除術，有關甲狀腺切除手術，下列何者正\n\n  確？①為維持正常的甲狀腺功能，一般採用次全甲狀腺切除 ②出血、聲門水腫、急性呼吸道阻塞為\n\n  常見的術後合併症 ③術後聲音沙啞是因雙側喉返神經受傷所致 ④術後需評估病人有無肌肉抽搐\n\n  之甲狀腺功能低下表徵", "options": ["①②", "①③", "②④", "③④"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-074", "year": 112, "session": "第一次", "no": 74, "stem": "74  下列何種情況可能會導致特魯索氏（Trousseau）與沃斯德克氏（Chvostek）徵象皆呈陽性反應？①低\n\n  血鈣 ②低血鉀 ③低血糖 ④副甲狀腺功能低下症", "options": ["①②", "①④", "②③", "③④"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112110-102-0203-003", "year": 112, "session": "第二次", "no": 3, "stem": "3 有關糖尿病病人運動之護理指導，下列何者正確？①運動可降低細胞對胰島素的敏感性而降低血糖\n\n  ②運動最好在飯後1～2 小時做 ③運動型態建議使用大肌肉群的有氧運動 ④切勿注射完胰島素後\n\n  立刻運動，以免發生高血糖現象", "options": ["①②", "①④", "②③", "③④"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112110&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112110-102-0203-068", "year": 112, "session": "第二次", "no": 68, "stem": "68 有關嗜鉻細胞瘤病人的護理措施，下列何者錯誤？", "options": ["注意有無頭痛、視力改變、胸痛、意識混亂等病症", "讓病人充分休息，避免壓力發生", "鼓勵攝取低維他命、低蛋白質、低礦物質及低熱量食物", "避免喝咖啡、茶"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112110&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112110-102-0203-069", "year": 112, "session": "第二次", "no": 69, "stem": "69 有關愛迪生氏危機病人的護理措施，下列何者錯誤？", "options": ["監測生命徵象、輸出入量、電解質", "執行限水計畫，每天攝水量少於1,000 c.c.", "鼓勵攝取含鈉及高蛋白質食物", "指導病人避免攝取香蕉、南瓜\n代號：3102\n頁次：8－8"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112110&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112110-102-0203-070", "year": 112, "session": "第二次", "no": 70, "stem": "70 有關胰島素保存之護理指導，下列何者正確？", "options": ["未開罐的胰島素可以在常溫中保存", "使用中的胰島素應冷藏2～8℃的環境", "出國旅遊勿將胰島素置於飛機行李艙", "開罐前若發現藥瓶內出現顆粒時需搖勻"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112110&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112110-102-0203-071", "year": 112, "session": "第二次", "no": 71, "stem": "71 有關胰島素注射之敘述，下列何者正確？", "options": ["吸收胰島素的速率依序是：腹部＞臀部＞大腿＞上臂", "建議將胰島素注射於即將運動的肢體上，避免吸收過慢", "注射同一部位應隔2～3 週才可重複，以防注射皮膚感染", "若糖尿病病人因感染而發燒，會加速胰島素藥效的吸收"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112110&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112110-102-0203-072", "year": 112, "session": "第二次", "no": 72, "stem": "72 有關升糖指數飲食指導之敘述，下列何者正確？①升糖指數是指人體食用含醣食物後，血中葡萄糖反\n\n  應的速度和強度 ②糖尿病人要選擇高升糖指數食物，以免造成低血糖 ③乳品類食物升糖指數較\n\n  高，常見的食物，如：全脂奶 ④全穀類食物升糖指數較低，常見的食物，如：全麥早餐穀類", "options": ["①②", "①④", "②③", "③④"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112110&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112110-102-0203-073", "year": 112, "session": "第二次", "no": 73, "stem": "73 有關第1 型糖尿病之敘述，下列何者錯誤？", "options": ["病因與自體免疫反應有關", "空腹血清C-胜肽濃度無法偵測", "會慢慢出現無症狀的高血糖情形", "常見合併症為酮酸中毒（DKA）"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112110&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112110-102-0203-074", "year": 112, "session": "第二次", "no": 74, "stem": "74 有關甲狀腺功能低下之臨床表徵，下列何者錯誤？", "options": ["周邊血管阻力增加", "聽診心臟有分裂音", "葡萄糖吸收增加", "惡性（巨球性）貧血"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112110&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112180-101-0103-043", "year": 112, "session": "第三次", "no": 43, "stem": "43 有關庫欣氏症候群症狀的病理機轉，下列何者錯誤？", "options": ["蛋白質過度分解，造成肌肉質塊流失", "肝臟糖質新生作用降低，胰島素利用增加", "水分與鈉離子滯留，導致水腫", "皮質醇分泌上升，造成淋巴球下降，傷口癒合差"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "112180-101-0103-044", "year": 112, "session": "第三次", "no": 44, "stem": "44 有關中樞性尿崩症的敘述，下列何者正確？", "options": ["尿比重大於1.030", "尿量少、血漿滲透壓下降", "有全身水腫現象", "因抗利尿激素分泌不足導致"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "112180-101-0103-046", "year": 112, "session": "第三次", "no": 46, "stem": "46 有關糖尿病病人飲食控制原則的護理指導，下列何者正確？", "options": ["儘量選用低升糖指數的食物，避免血糖上升快速，如：根莖類、瓜果類", "避免油炸，宜多採用清蒸、水煮、清燉、滷、涼拌等烹調方式", "避免喝酒，有小酌嗜好者，可選擇雙鹿五加皮、蔘茸酒、玫瑰露酒等", "脂肪需求量占每日總熱量的20～30%，膽固醇每日攝取量低於500 mg"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "112180-101-0103-047", "year": 112, "session": "第三次", "no": 47, "stem": "47 有關甲狀腺功能亢進病人的飲食指導，下列何者不適當？", "options": ["高熱量", "高碳水化合物", "高蛋白", "高纖維"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "113100-102-0203-042", "year": 113, "session": "第二次", "no": 42, "stem": "42 有關腎上腺皮質功能低下症之敘述，下列何者錯誤？", "options": ["原發性腎上腺皮質功能不全常因腎上腺皮質慢性破壞所致", "通常在至少有10%的腎上腺皮質組織被破壞後，即會出現明顯症狀", "原發性腎上腺皮質功能不全病人常因促黑色細胞素（MSH）的過多分泌而使皮膚變深", "下視丘分泌的促腎上腺皮質素釋放因子（CRF）不足亦會導致腎上腺皮質功能低下"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "113100-102-0203-043", "year": 113, "session": "第二次", "no": 43, "stem": "43 下列何者是與糖尿病小血管病變有關的慢性合併症？①足部神經麻木 ②糖尿病腎病變 ③心肌梗塞\n  ④腦血管梗塞", "options": ["①②", "①③", "②④", "③④"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "113100-102-0203-044", "year": 113, "session": "第二次", "no": 44, "stem": "44 有關尿崩症臨床表徵之敘述，下列何者錯誤？", "options": ["多尿", "煩渴", "尿比重降低", "體液容積過剩"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "113100-102-0203-045", "year": 113, "session": "第二次", "no": 45, "stem": "45 有關胰島素的使用，下列何者錯誤？", "options": ["準備胰島素前30 分鐘，將胰島素自冰箱取出，避免注射冷的胰島素", "抽取混濁型的胰島素應先將藥瓶置於手掌中滾動，不可搖晃藥瓶，避免產生氣泡", "胰島素推入皮下後需靜待3～5 秒再拔出針頭，且以藥棉輕壓，切勿搓揉", "皮下注射胰島素的吸收速率，上臂＞大腿＞臀部＞腹部"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "113100-102-0203-046", "year": 113, "session": "第二次", "no": 46, "stem": "46 下列何者是副甲狀腺功能亢進的臨床表徵？", "options": ["骨痛、便秘", "少尿、尿比重上升", "胃泌素分泌減少，引起萎縮性胃炎", "鈣沉積在眼睛組織形成凸眼症"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "113180-101-0103-009", "year": 113, "session": "第三次", "no": 9, "stem": "9 有關副甲狀腺功能亢進之敘述，下列何者正確？", "options": ["要鼓勵病人多攝取奶類製品", "病人會有多尿、尿比重下降、腎結石等臨床表徵", "要限制每日水分攝取量在1500c.c.以下", "病人會有高血磷"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "113180-101-0103-015", "year": 113, "session": "第三次", "no": 15, "stem": "15 下列檢查結果，何者可診斷為糖尿病？", "options": ["禁食8 小時空腹血漿葡萄糖（fasting plasma glucose, FPG）110 mg/dL", "口服葡萄糖耐量試驗（OGTT）第2 小時血漿葡萄糖159 mg/dL", "糖化血紅素（HbA1c）7%", "隨意抽血一次血漿葡萄糖240 mg/dL"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "113180-101-0103-042", "year": 113, "session": "第三次", "no": 42, "stem": "42 有關愛迪生危機的特徵，下列何者正確？", "options": ["高血鉀", "高血壓", "高血糖", "高血鈉"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "113180-101-0103-043", "year": 113, "session": "第三次", "no": 43, "stem": "43 有關尿崩症病人的出院護理指導，下列何者錯誤？", "options": ["教導避免食用會利尿的飲料與食物", "教導使用desmopressin（DDAVP）鼻噴霧劑時勿憋氣，並須確認藥劑確實有吸入肺部", "教導病人睡前少喝水，減少夜晚環境上的刺激", "教導病人用藥的方式、劑量、時間及副作用，並定期返院追蹤"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "113180-101-0103-044", "year": 113, "session": "第三次", "no": 44, "stem": "44 有關糖尿病病人足部護理的指導，下列何者正確？①每日以溫水清洗足部前須以手背測試水溫，以防燙傷\n  ②修剪趾甲應剪短於足趾末端，以防甲溝炎 ③平日於足部與足趾間及腳跟龜裂處，塗抹保養乳液，以免\n  皮膚過於乾燥 ④不可擅自用手或剪刀，將足部硬繭或雞眼剝除", "options": ["①②", "①④", "②③", "③④"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "113180-101-0103-045", "year": 113, "session": "第三次", "no": 45, "stem": "45 有關庫欣氏症候群（Cushing’s syndrome）的臨床表徵，下列何者正確？", "options": ["低血鉀性鹼中毒", "皮膚變厚成水牛肩", "體毛及鬢毛減少", "葡萄糖新生減少"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "113180-101-0103-046", "year": 113, "session": "第三次", "no": 46, "stem": "46 有關腦下垂體中風之臨床表徵，下列何者錯誤？", "options": ["荷爾蒙失調", "頭痛、脖子僵硬", "畏光、視力受損", "肢體半側偏癱"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "114100-102-0203-042", "year": 114, "session": "第二次", "no": 42, "stem": "42 有關腦下垂體前葉分泌的激素，下列何者正確？①生長素（growth hormone）  ②促乳素（prolactin）\n   ③催產素（oxytocin） ④抗利尿素（ADH）", "options": ["①②", "①④", "②③", "③④"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "114100-102-0203-044", "year": 114, "session": "第二次", "no": 44, "stem": "44 有關尿崩症病人之臨床表徵，下列何者錯誤？", "options": ["黏膜乾燥", "眼眶凹陷", "心搏下降", "脈搏呈絲脈"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "114100-102-0203-045", "year": 114, "session": "第二次", "no": 45, "stem": "45 有關糖尿病足部之身體評估可能結果，下列何者錯誤？", "options": ["足部的外形改變", "皮膚乾燥造成裂隙", "腳趾的震動覺消失", "跟腱肌腱反射+++"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "114100-102-0203-046", "year": 114, "session": "第二次", "no": 46, "stem": "46 有關副甲狀腺機能亢進造成的影響，下列何者錯誤？", "options": ["促進腸道對鈣質的吸收", "促進維生素D 活化", "促進腎小管對鈣的再吸收", "促進骨鈣形成"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "114170-101-0103-017", "year": 114, "session": "第三次", "no": 17, "stem": "17  58 歲中年婦女，平日血壓約為138/88 mmHg，沒有糖尿病與其他心血管疾病，BMI 為30 kg/m2，飲食偏好\n  重油滷肉類食物，沒有抽菸與喝酒習慣，日常活動多為家務勞動，下列敘述何者最不適當？", "options": ["控制熱量的攝取", "限制高鈉食物的攝取", "每天至少30 分鐘的中等強度運動", "積極使用藥物來控制血壓"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114170&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "114170-101-0103-041", "year": 114, "session": "第三次", "no": 41, "stem": "41 有關中樞性尿崩症，下列敘述何者最適當？", "options": ["尿比重1.050", "血漿滲透壓290 mOsm/kg", "多尿、劇渴、心搏過速", "體液容積過多"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114170&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "114170-101-0103-042", "year": 114, "session": "第三次", "no": 42, "stem": "42 有關副甲狀腺功能低下病人之處置，下列敘述何者最不適當？", "options": ["可補充鈣鹽及維生素D", "急性期需密切觀察呼吸道是否通暢", "應多攝取高磷食物，例如：肉類、蛋、乳酪等食物", "在進餐時或飯前可服用氫氧化鋁"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114170&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "114170-101-0103-045", "year": 114, "session": "第三次", "no": 45, "stem": "45 有關造成糖尿病人血糖過高之促因，下列敘述何者最不適當？", "options": ["注射NPH 或Lente insulin 量過少", "近日下肢被診斷蜂窩性組織炎", "近期因業績需求工作壓力增加", "食量減少而健走運動時間增加"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114170&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "115100-102-0203-001", "year": 115, "session": "第二次", "no": 1, "stem": "1 腦下垂體腫瘤病人接受經蝶骨腫瘤切除術後第4 天，持續有流鼻水、頭痛現象，下列處置之敘述何者正確？", "options": ["手術傷口是在頭部頂葉及顳葉處，須每日給與換藥", "給與減少流鼻水藥物，以免咳嗽造成顱內壓升高", "教導病人不要擤鼻涕，目前不宜下床活動", "可從鼻腔進行抽吸，以促進呼吸道暢通"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=115100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "115100-102-0203-043", "year": 115, "session": "第二次", "no": 43, "stem": "43 有關抗利尿不當症候群（SIADH）的臨床表徵，下列何者正確？①血鈉128 mEq/L ②尿鈉40 mEq/L\n   ③尿比重1.050 ④血漿滲透壓350 mOsmo/kg ⑤尿液滲透壓50 mOsmo/kg", "options": ["①②③", "②③④", "③④⑤", "①④⑤"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=115100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "115100-102-0203-045", "year": 115, "session": "第二次", "no": 45, "stem": "45 副甲狀腺切除術後易發生下列何種現象？", "options": ["低血磷", "低血鈣", "低血糖", "低血鉀"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=115100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "115100-102-0203-046", "year": 115, "session": "第二次", "no": 46, "stem": "46 有關第1 型與第2 型糖尿病比較之敘述，下列何者錯誤？", "options": ["第2 型的病因可能與體內胰島素接受器的數目降低有關", "第2 型病程緩慢初期通常無症狀，或症狀輕微", "絕大多數的糖尿病病人，都是屬於第2 型糖尿病", "多數體型偏瘦，多尿頻渴，有明顯第2 型糖尿病史"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=115100&c=102&s=0203&q=1", "status": "needs_visual_review"}], "5": [{"id": "106030-106-0503-038", "year": 106, "session": "第一次", "no": 38, "stem": "38 有關再生不良性貧血之敘述，下列何者錯誤？", "options": ["紅血球數目會減少，白血球或血小板則不受影響", "可採用血液幹細胞移植的治療", "活動時出現胸痛或呼吸短促可能是活動過度所致", "宜少量多餐，進食高蛋白或富含維生素的食物"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106030-106-0503-050", "year": 106, "session": "第一次", "no": 50, "stem": "50 下列何者屬於免疫複合體性之過敏反應？", "options": ["異位性皮膚炎", "ABO 血型不合", "類風濕性關節炎", "器官移植排斥反應"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-011", "year": 106, "session": "第二次", "no": 11, "stem": "11 下列何者顯示結腸造口病人可能有貧血現象？", "options": ["造口呈藍紫色", "造口嚴重水腫", "造口呈蒼白色", "造口呈粉紅色"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-037", "year": 106, "session": "第二次", "no": 37, "stem": "37 有關缺鐵性貧血口服鐵劑護理措施的敘述，下列何者錯誤？", "options": ["鼓勵與牛奶共食", "鼓勵與果汁一起服用", "避免同時服用制酸劑", "應於二餐之間服用"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-040", "year": 106, "session": "第二次", "no": 40, "stem": "40 有關造成大量凝血活酶釋入血液中，導致凝血因子全面活化，促使全身血管內凝血之情況，下列何\n\n  者錯誤？", "options": ["敗血症", "羊水栓塞", "毒蛇咬傷", "慢性淋巴性白血病"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-046", "year": 106, "session": "第二次", "no": 46, "stem": "46  有關HIV 疾病進展的敘述，下列何者錯誤？", "options": ["HIV 的抗體可阻止HIV 感染的發展", "HIV 感染者CD4 小於200/μL 時，易發生伺機性感染", "首次感染HIV 後2～4 星期，50%以上的病人會出現短暫類似感冒的症狀", "卡波西氏肉瘤是愛滋病最常見的惡性腫瘤"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-047", "year": 106, "session": "第二次", "no": 47, "stem": "47 有關發生急性溶血性輸血反應處置之敘述，下列何者錯誤？", "options": ["密切監測生命徵象", "輸血不能中斷", "收集血液及尿液標本送檢", "記錄輸出入量"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-048", "year": 106, "session": "第二次", "no": 48, "stem": "48 有關過敏性疾病的實驗室檢查，下列何者錯誤？", "options": ["血清IgE 的濃度上升", "C3、C4 補體下降", "嗜伊紅球（嗜酸性球）上升", "白血球下降\n代號：3106\n頁次：6－5"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-078", "year": 106, "session": "第二次", "no": 78, "stem": "78 有關末期腎疾病（ESRD）病人，因腎性貧血接受紅血球生成素（EPO）治療之準則，下列何者錯誤？", "options": ["血球比容至少要達到35%", "血清鐵蛋白應大於200 ng/mL", "運鐵蛋白飽和度應大於20%", "無惡性高血壓"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-041", "year": 106, "session": "第二次", "no": 41, "stem": "41 有關血小板減少症臨床表徵之敘述，下列何者錯誤？", "options": ["血小板過低症是指血小板小於100,000/mm3", "血小板大於30,000/mm3，沒有嚴重的出血，通常不需要治療", "可能會有顱內壓上升、頭痛、意識改變等中樞神經系統異常症狀", "黏膜或皮膚不容易出現紫斑或瘀斑"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-042", "year": 106, "session": "第二次", "no": 42, "stem": "42 有關急性瀰慢性血管內凝血病人之實驗室檢查結果，下列何者錯誤？", "options": ["血小板減少", "凝血酶原時間（PT）及活化部分凝血活酶時間（aPTT）延長", "纖維蛋白原（fibrinogen）濃度上升", "纖維蛋白分解物（FDP）濃度增加"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-047", "year": 106, "session": "第二次", "no": 47, "stem": "47 愛滋病毒感染者的伺機性感染，下列何者最常見？", "options": ["肺囊蟲肺炎", "弓形蟲腦膜炎", "隱球菌症", "念珠菌感染口腔炎"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-048", "year": 106, "session": "第二次", "no": 48, "stem": "48 溶血性之輸血反應是屬於下列那一種過敏反應？", "options": ["免疫複合體性過敏反應", "過敏性休克反應", "遲發性過敏反應", "細胞毒性過敏反應"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-033", "year": 107, "session": "第一次", "no": 33, "stem": "33 手術後輸血導致出現溶血性黃疸所造成之檢驗值變化，下列何者正確？", "options": ["肝功能指數正常", "凝血酶原時間延長", "尿膽紅素增加", "結合型血清膽紅素增加"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-042", "year": 107, "session": "第一次", "no": 42, "stem": "42 有關輸注血小板的注意事項，下列敘述何者錯誤？", "options": ["輸注血小板速度應愈慢愈好，因可避免血小板凝集產生血栓", "輸注血小板後，若出現過敏反應，可依醫囑給與抗組織胺、類固醇等藥物", "當反覆多次輸注血小板後，若出現輸注效果不佳，可考慮使用單一供血者的血小板", "輸注血小板後，若出現寒顫、發燒是輸血之熱原反應"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-047", "year": 107, "session": "第一次", "no": 47, "stem": "47  一位28 歲的發燒男性病人，護理師抽取血液培養過程中不慎針扎，病人之愛滋病毒、B 型肝炎病毒、\n\n   C 型肝炎病毒抗體皆呈陽性。下列敘述何者錯誤？", "options": ["急性愛滋病毒感染空窗期約是愛滋病毒感染後6～12 週內，亦可能長達12 個月", "針扎事件後24 小時內開始使用暴露後預防的抗愛滋病毒藥物，可降低感染HIV 的機會", "針扎事件後，發生病毒傳染的風險高低為HBV（HBeAg（+））＞HIV＞HCV", "針扎事件後，應定期檢驗並追蹤至一年\n代號：3106\n頁次：8－6"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-048", "year": 107, "session": "第一次", "no": 48, "stem": "48 有關急性溶血性輸血反應之症狀，下列何者最不可能出現？", "options": ["寒顫、發燒", "下背痛", "血管怒張", "急性腎衰竭"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-049", "year": 107, "session": "第一次", "no": 49, "stem": "49 有關過敏性疾病的護理指導，下列何者錯誤？", "options": ["儘量使用尼龍枕頭", "儘量使用羽絨被", "風大的天氣戴口罩", "避免使用絨毛玩具"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-074", "year": 107, "session": "第一次", "no": 74, "stem": "74 有關淋巴瘤的國際性預後指標，下列何者錯誤？", "options": ["診斷時的年齡", "乳酸脫氫酶（LDH）數值", "性別", "腫瘤分期"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107110-106-0503-039", "year": 107, "session": "第二次", "no": 39, "stem": "39 有關白血病檢查與治療之敘述，下列何者錯誤？", "options": ["嗜中性白血球是免疫力的指標", "化學治療是主要的治療方式", "可將化學藥物直接注入骨髓以預防中樞神經系統受侵犯", "化學治療後兩週左右，白血球會降到最低\n代號：3106\n頁次：6－4"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107110-106-0503-042", "year": 107, "session": "第二次", "no": 42, "stem": "42 有關缺鐵性貧血病人鐵劑補充之敘述，下列何者錯誤？", "options": ["指導病人鐵劑可與維生素C 一起服用", "植物性鐵劑較動物性鐵劑容易吸收", "鐵劑注射要採Z 型注射法", "鐵劑注射後要觀察是否發生過敏現象"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107110-106-0503-043", "year": 107, "session": "第二次", "no": 43, "stem": "43 有關惡性貧血之敘述，下列何者錯誤？", "options": ["觀察病人是否出現手足針刺麻木感或運動協調能力變差", "一般會出現蒼白、呼吸困難或心悸的症狀", "可採用費城染色體檢查以確定診斷", "病人需終生肌肉注射維生素B12"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107110-106-0503-045", "year": 107, "session": "第二次", "no": 45, "stem": "45 關於瀰漫性血管內凝血病人的敘述，下列何者代表護理師需要重新指導預防出血的方法？", "options": ["可以用力解便", "可以使用電鬍刀刮鬍子", "不要用力咳嗽及擤鼻涕", "不用牙線，使用軟毛牙刷刷牙"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107110-106-0503-050", "year": 107, "session": "第二次", "no": 50, "stem": "50 有關愛滋病防治之敘述，下列何者正確？", "options": ["「全面性防護」是將所有人的血液、體液均視為感染性，以預防未篩檢出的疾病入侵", "發生不安全性行為後，可立即至捐血中心捐血，以檢驗是否感染HIV 病毒", "HIV（+）之孕婦於懷孕12 週後開始服用抗病毒藥物，可採自然生產", "服用預防性抗病毒藥可防止靜脈注射藥癮者感染HIV 病毒"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107110-106-0503-066", "year": 107, "session": "第二次", "no": 66, "stem": "66 梁先生每週一、三、五下午1 點至5 點接受血液透析，因腎性貧血服用維生素C 與葉酸，其服用時\n  間下列何者正確？", "options": ["中午12 點與中餐一起服用", "下午1 點開始透析時服用", "下午3 點透析中服用", "下午5 點透析結束時服用"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-035", "year": 108, "session": "第一次", "no": 35, "stem": "35 汪小姐，血小板數目為40,000/mm3，下列敘述何者正確？①非常容易引起自發性出血 ②避免使用\n     Aspirin 或Heparin ③肌肉注射的給藥方式最佳 ④給與軟便藥物可減少排便腸黏膜受傷", "options": ["①②", "①③", "②④", "③④"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-040", "year": 108, "session": "第一次", "no": 40, "stem": "40  維生素B12 缺乏造成的惡性貧血，可透過下列何種試驗或檢查進行鑑別？", "options": ["直接庫姆氏試驗（direct Coombs’ test）", "間接庫姆氏試驗（indirect Coombs’ test）", "席林試驗（Schilling’s test）", "尿液本斯-瓊司氏蛋白檢查（Bence-Jones protein）\n代號：3106\n頁次：6－4"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-041", "year": 108, "session": "第一次", "no": 41, "stem": "41  王太太50 歲，診斷為急性白血病，入院行高劑量Ara-C 化學治療後，白血球3,500/cumm、嗜中性球\n  為13%，下列敘述何者正確？", "options": ["王太太屬輕度白血球低下，應提供居家照護護理指導後辦理出院", "王太太正處於嗜中性白血球低下（neutropenia）的階段", "王太太沒有發燒、呼吸急促或解尿困難等症狀，表示未感染，出院後自行觀察即可", "王太太的口腔黏膜、肛門黏膜和侵入性導管置入處不可能會發生感染"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-042", "year": 108, "session": "第一次", "no": 42, "stem": "42 有關非何杰金氏淋巴瘤之治療，下列何者正確？", "options": ["病人常接受低劑量類固醇", "周邊血液幹細胞移植法不適用於復發病人", "在化療後一個月取出病人骨髓，除去癌細胞後儲存", "化療前接受HBsAg 篩檢，並使用lamivudine，以防B 型肝炎急性發作"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-047", "year": 108, "session": "第一次", "no": 47, "stem": "47  針對HIV 感染或HIV 感染狀況不明者的相關防範措施之敘述，下列何者錯誤？", "options": ["接觸血液或其他可能帶有血液的體液（例如尿液、糞便、嘔吐物）時，應該要戴手套", "HIV 病毒可存在於母乳中，因此感染愛滋病毒的婦女不要哺餵母乳", "發現環境表面有血液沾污時，立刻以1：1000 之漂白水清潔消毒", "愛滋病毒感染者若需急救時，避免口對口人工呼吸"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-048", "year": 108, "session": "第一次", "no": 48, "stem": "48 有關溶血性輸血引起的過敏反應，是下列那類免疫球蛋白與補體結合，活化補體系統所致？", "options": ["IgA、IgM", "IgA、IgE", "IgE、IgM", "IgG、IgM"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108110-106-0503-005", "year": 108, "session": "第二次", "no": 5, "stem": "5 有關照護HIV 感染者及共同生活者之護理指導，下列何者正確？", "options": ["與愛滋病毒感染者進行性行為時，肛交是危險的性交行為，口交是安全的", "與愛滋病毒感染者共同生活，沒有發生性行為，不易感染HIV 病毒", "提供感染者低熱量高蛋白飲食，應避免生食，以避免感染", "未取得病人同意前，可主動告知其主要照顧者有關疾病診斷及照護事項"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108110-106-0503-030", "year": 108, "session": "第二次", "no": 30, "stem": "30 有關惡性貧血病人特徵之敘述，下列何者錯誤？", "options": ["紅血球數目減少", "紅血球外觀小且形狀不規則", "膽紅素上升", "舌炎、皮膚發黃"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108110-106-0503-035", "year": 108, "session": "第二次", "no": 35, "stem": "35 有關急性骨髓性白血病病人在接受異體骨髓移植後3 週，出現全身紅疹與腹瀉症狀，下列敘述何者錯誤？", "options": ["應注意肝功能異常與血中膽紅素上升", "可進行皮膚切片以確定問題", "皮膚同時可能會出現斑丘疹", "顯示為嚴重藥物過敏"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108110-106-0503-049", "year": 108, "session": "第二次", "no": 49, "stem": "49  HIV 抗體試驗呈陽性，且T4 細胞數目為650 cells/mm3、占所有淋巴球之35%的病人，最可能處在\n    HIV 疾病那一期？", "options": ["空窗期", "潛伏期", "急性感染期", "伺機性感染期"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108110-106-0503-052", "year": 108, "session": "第二次", "no": 52, "stem": "52 肺栓塞病人使用肝素以阻止新的血塊形成，通常須維持部分凝血活酶時間（aPTT）為正常值的多少倍？", "options": ["1.0～1.4", "1.5～2.5", "2.6～3.5", "3.6～4.5\n代號：3106\n頁次：6－5"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-033", "year": 109, "session": "第一次", "no": 33, "stem": "33 病人的皮膚黏膜蒼白、舌頭發炎呈紅色平滑狀，指甲萎縮、變薄呈湯匙狀，可能罹患下列何種貧血？", "options": ["葉酸缺乏性貧血", "缺鐵性貧血", "惡性貧血", "再生不良性貧血"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-035", "year": 109, "session": "第一次", "no": 35, "stem": "35 當癌症病人出現下列何種血液檢驗數據時，要考慮停止化學治療？①白血球1,500/μL ②紅血球\n     500 萬/μL ③血小板11 萬/μL ④絕對嗜中性球1,000/μL", "options": ["①②", "①④", "②③", "③④"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-044", "year": 109, "session": "第一次", "no": 44, "stem": "44 有關過敏性休克之敘述，下列何者錯誤？", "options": ["過敏反應發生後數分鐘內休克，可能會有死亡的危機", "因接觸外來物質所引起，如藥物、花粉、灰塵等", "由嗜酸性細胞釋出具血管活性的介質，如組織胺、白三烯素", "再次碰到相同過敏原，會產生大量抗體IgE"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-045", "year": 109, "session": "第一次", "no": 45, "stem": "45  一位30 歲女性主訴最近出現皮膚對光敏感、對稱性關節疼痛、口腔潰瘍，另補體C3 及C4 減少、抗\n  核抗體（ANA）呈現陽性、紅血球沉降速率（ESR）明顯上升、血小板減少，下列何者為其最可能\n  之診斷？", "options": ["痛風性關節炎", "後天免疫缺乏症候群", "全身性紅斑性狼瘡", "類風濕性關節炎"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-046", "year": 109, "session": "第一次", "no": 46, "stem": "46 有關治療類風濕性關節炎使用之藥物，下列何者不適當？", "options": ["水楊酸藥物，如aspirin", "免疫抑制劑，如methotrexate", "糖皮質類固醇，如prednisone", "利尿劑，如furosemide（Lasix）"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-047", "year": 109, "session": "第一次", "no": 47, "stem": "47 愛滋病病人感染肺囊蟲肺炎之初期主要症狀，下列何者正確？", "options": ["體重下降", "皮疹", "氣喘", "乾咳"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-078", "year": 109, "session": "第一次", "no": 78, "stem": "78 有關過敏性休克的治療與護理指導，下列何者錯誤？", "options": ["治療的目標是緩解症狀", "避免接觸過敏原或食用引起過敏的食物", "給予藥物或生物性製劑需先行皮膚試驗", "減敏感療法之目的在增加IgE 的濃度"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-036", "year": 109, "session": "第二次", "no": 36, "stem": "36 依據安阿伯（Ann Arbor）臨床分期系統，下列何者屬於何杰金氏淋巴瘤第Ⅱ期？", "options": ["侵犯多個淋巴結以外的器官或組織", "侵犯單一淋巴結區域外器官", "侵犯橫膈膜同側2 個以上淋巴結區域", "侵犯橫膈膜兩側淋巴結區域"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-047", "year": 109, "session": "第二次", "no": 47, "stem": "47 有關遲發型過敏反應之敘述，下列何者錯誤？", "options": ["抗體與抗原結合形成免疫複合體，隨血液循環四處沉積所導致", "器官移植後排斥反應屬此類過敏反應", "可能因接觸化學物質，如染劑、藥物等物質刺激產生的過敏反應", "病毒或細菌侵入後，刺激T 細胞引發細胞性免疫反應"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-049", "year": 109, "session": "第二次", "no": 49, "stem": "49 有關照護愛滋病人防護措施之敘述，下列何者正確？", "options": ["使用過的針頭應與針筒分開處理，針頭置於堅硬不易刺破的容器內", "若不慎接觸糞便須立刻口服400 mg 反轉錄酶抑制劑（AZT）", "若衣物被病人分泌物污染，應以漂白水浸泡後再清洗", "若不慎被針扎應持續追蹤3 個月，抽血檢驗結果為陰性即可排除感染"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-051", "year": 109, "session": "第二次", "no": 51, "stem": "51 下列何者不屬於第三型過敏性反應？", "options": ["全身性紅斑狼瘡", "類風濕性關節炎", "溶血性反應", "血清病"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-035", "year": 110, "session": "第一次", "no": 35, "stem": "35 有關貧血病因的敘述，下列何者正確？", "options": ["海洋性貧血，因造血骨髓被破壞或功能受到抑制", "鐮狀細胞貧血，因血小板被破壞所致", "再生不良性貧血，因骨髓被破壞或功能受到抑制", "缺鐵性貧血，因血紅素的結構異常所致"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-037", "year": 110, "session": "第一次", "no": 37, "stem": "37 有關慢性淋巴性白血病的敘述，下列何者錯誤？", "options": ["好發於50 歲以上成人", "分期較早通常不需治療", "小且異常的不成熟淋巴球增生", "容易造成嚴重感染"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-039", "year": 110, "session": "第一次", "no": 39, "stem": "39 有關血小板減少症照護的敘述，下列何者正確？", "options": ["病人可使用非類固醇抗發炎之止痛藥物", "教導病人使用牙線代替牙籤", "教導病人避免做閉氣用力的動作", "鼻黏膜乾燥不適，不可塗抹凡士林"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-041", "year": 110, "session": "第一次", "no": 41, "stem": "41  有關骨髓移植後病人產生移植物抗宿主疾病（Graft-versus-host Disease; GVHD）症狀，下列何者錯誤？", "options": ["膽紅素上升", "皮疹", "肝功能受損", "便祕\n代號：3104\n頁次：6－4"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-042", "year": 110, "session": "第一次", "no": 42, "stem": "42 下列何者不是嚴重缺鐵性貧血病人常見的症狀？", "options": ["吞嚥困難", "舌炎、口炎", "湯匙狀指甲", "手足有麻木感"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-048", "year": 110, "session": "第一次", "no": 48, "stem": "48 有關愛滋病檢驗的敘述，下列何者正確？", "options": ["T4 與T8 的比值大於1", "當CD4 細胞小於400/μl 時，容易出現伺機性感染", "沒有空窗期", "西方墨點試驗是一種確定診斷的檢驗法"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-050", "year": 110, "session": "第一次", "no": 50, "stem": "50 有關類風濕性關節炎的醫療處置，下列敘述何者正確？", "options": ["非類固醇抗炎藥物Ibuprofen 最需擔心肝腎功能損傷問題", "DMARDs 為育齡婦女治療的首選藥物", "COX-2 抑制劑有延長出血時間的副作用", "使用抗瘧疾製劑（奎寧類），應定期檢查眼睛"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-078", "year": 110, "session": "第一次", "no": 78, "stem": "78 有關敗血性休克引發瀰漫性血管內凝血（DIC）之敘述，下列何者正確？", "options": ["體內會產生凝血因子和血小板功能被抑制", "DIC 產生之症狀包括皮膚出現水泡", "應優先治療敗血症之導因", "DIC 治療包括優先提供全血輸注"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-026", "year": 110, "session": "第二次", "no": 26, "stem": "26  使用Warfarin（Coumadin○R ）預防深部靜脈栓塞（deep vein thrombosis, DVT）之護理指導，下列何者\n  正確？①需定期監測凝血酶原時間（PT） ②鼓勵多攝取銀杏、當歸 ③若出現血尿是正常的現象不\n  需理會 ④宜使用電動刮鬍刀", "options": ["①③", "①④", "②③", "②④"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-037", "year": 110, "session": "第二次", "no": 37, "stem": "37 病人接受化學治療後血小板數值為10,000 cells/mm，下列何者為護理評估重點？", "options": ["意識狀態", "體溫變化", "腸蠕動音", "皮膚飽和度"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-038", "year": 110, "session": "第二次", "no": 38, "stem": "38 有關何杰金氏淋巴瘤的敘述，下列何者錯誤？", "options": ["淋巴組織切片中可發現瑞德-史登伯氏細胞（Reed-Sternberg cell）", "會侵犯淋巴結、肝臟及脾臟", "好發於女性老年人", "疾病預後與分期有關\n代號：3104\n頁次：6－4"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-043", "year": 110, "session": "第二次", "no": 43, "stem": "43 有關席林試驗可協助診斷的貧血類別，下列何者正確？", "options": ["缺鐵性貧血", "惡性貧血", "溶血性貧血", "再生不良性貧血"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-050", "year": 110, "session": "第二次", "no": 50, "stem": "50 有關愛滋病的傳染途徑，下列何者錯誤？", "options": ["垂直傳染", "血液傳染", "性行為傳染", "飲食傳染\n代號：3104\n頁次：6－5"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-051", "year": 110, "session": "第二次", "no": 51, "stem": "51 下列何者不屬於第Ⅰ型過敏反應？", "options": ["接觸性皮膚炎", "氣喘", "枯草熱", "異位性皮膚炎"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111030-104-0303-015", "year": 111, "session": "第一次", "no": 15, "stem": "15 有關癌症病人貧血問題之敘述，下列何者錯誤？", "options": ["全胃或脾臟切除手術會影響病人紅血球的生成", "貧血症狀包括蒼白、心跳變慢、血壓上升、易疲倦等", "鼓勵病人補充鐵質和含葉酸食物，如牛肉、綠色蔬菜", "集中護理可讓病人獲得充分的休息"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111030-104-0303-035", "year": 111, "session": "第一次", "no": 35, "stem": "35 有關缺鐵性貧血病人的護理措施，下列何者正確？①教導病人使用吸管吸食液態鐵劑 ②鼓勵病人\n  飯後服用鐵劑以增加鐵的吸收 ③鼓勵病人多攝取富含維生素C 的食物 ④注射鐵劑後應避免立即\n  拔出針頭", "options": ["①②③", "①②④", "①③④", "②③④"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111030-104-0303-036", "year": 111, "session": "第一次", "no": 36, "stem": "36 林先生接受骨髓移植後2 週出現黃疸、腹水、體重增加，下列何者為最可能發生之合併症？", "options": ["感染", "間質性肺炎", "肝靜脈阻塞疾病", "慢性移植物對抗宿主疾病"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111030-104-0303-037", "year": 111, "session": "第一次", "no": 37, "stem": "37 有關白血病病人接受異體骨髓移植後出現合併症之敘述，下列何者錯誤？", "options": ["移植前曾罹患肝炎者會增加肝靜脈阻塞的機率", "急性移植物對抗宿主疾病以皮膚、腸胃道及肝臟為主", "慢性移植物對抗宿主疾病的發生率與年齡有關", "移植後2 星期內的感染以巨細胞病毒感染最常見"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111030-104-0303-038", "year": 111, "session": "第一次", "no": 38, "stem": "38 有關特異性血小板減少性紫斑症之敘述，下列何者正確？①可能與自體免疫疾病有關 ②骨髓檢查\n  可發現巨核細胞增加 ③須避免使用Aspirin 的藥物 ④經常發生於細菌感染後", "options": ["①②③", "①②④", "①③④", "②③④"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111030-104-0303-050", "year": 111, "session": "第一次", "no": 50, "stem": "50 有關類風濕性關節炎之敘述，下列何者正確？①手部關節會出現尺側偏斜 ②活動後有僵硬的現象\n  ③關節X 光變化呈現關節腔變窄 ④關節腫脹呈現不對稱性", "options": ["①②", "①③", "②④", "③④"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111030-104-0303-064", "year": 111, "session": "第一次", "no": 64, "stem": "64 梁太太規律接受血液透析，因腎性貧血服用葉酸，其最恰當的服用時間為何？", "options": ["透析前半小時服用", "開始透析時立即服用", "透析當中服用", "透析結束後服用"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111030-104-0303-079", "year": 111, "session": "第一次", "no": 79, "stem": "79 病人輸血10 分鐘時出現蕁麻疹及哮喘之處置，下列何者錯誤？", "options": ["需密切監測生命徵象的變化", "暫停輸血5 分鐘，再繼續進行輸血", "維持呼吸道暢通", "給予Epinephrine 及Aminophylline"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-040", "year": 111, "session": "第二次", "no": 40, "stem": "40 林先生在輸血過程中出現頭痛、咳嗽、呼吸困難、心跳加快及血壓升高等情形，最有可能是出現下列\n  那一種輸血反應？", "options": ["急性溶血反應", "循環過度負荷", "過敏反應", "輸血相關之急性肺損傷"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-048", "year": 111, "session": "第二次", "no": 48, "stem": "48 有關過敏反應護理指導的敘述，下列何者錯誤？", "options": ["建議關閉門窗以隔離髒空氣及過敏原，並打開空調讓室內的空氣循環", "建議使用填充家具，如布沙發、椰子墊、草蓆、榻榻米等", "定期清理住家環境，且不使用噴霧清潔劑", "避免飼養寵物，或服用容易引起過敏的食物"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-049", "year": 111, "session": "第二次", "no": 49, "stem": "49 有關愛滋病病人護理指導的敘述，下列何者正確？", "options": ["鼓勵多食用生菜，以促進維生素之攝取", "勿與剛接種疫苗或受傳染病感染的家人接觸", "服用Zidovudine 反轉錄酶抑制劑，需注意末梢神經痛的症狀", "勿握手、擁抱、共用餐具、共用浴池，以避免傳染他人"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-051", "year": 111, "session": "第二次", "no": 51, "stem": "51 下列何者為與第一型立即性過敏反應有密切關聯的免疫球蛋白？", "options": ["IgA", "IgE", "IgG", "IgM"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-034", "year": 112, "session": "第一次", "no": 34, "stem": "34 有關非何杰金氏淋巴瘤預後不佳的因素，下列何者正確？①年齡小於50 歲 ②身體功能狀態不佳\n\n  ③淋巴結外侵犯 ④血紅素值小於12 g/dL", "options": ["①②③", "①②④", "①③④", "②③④"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-035", "year": 112, "session": "第一次", "no": 35, "stem": "35 有關瀰漫性血管內凝血的敘述，下列何者正確？①與感染有關 ②常出現凝血症狀 ③檢查時纖維\n\n  蛋白原下降 ④常出現出血症狀", "options": ["①②③", "①②④", "①③④", "②③④"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-040", "year": 112, "session": "第一次", "no": 40, "stem": "40 有關癌症病人血小板減少症之處置，下列何者正確？", "options": ["可給與非類固醇抗發炎藥物緩解疼痛", "必要時輸注凝血因子避免自發性出血", "給與Bisacodyl supp 避免便秘而閉氣用力", "天冷時鼻黏膜塗擦凡士林保濕"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-042", "year": 112, "session": "第一次", "no": 42, "stem": "42 下列那一類白血病的預後最好？", "options": ["T 細胞型急性淋巴性", "B 細胞型急性淋巴性", "血小板缺乏的慢性淋巴性", "芽細胞期慢性骨髓性"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-047", "year": 112, "session": "第一次", "no": 47, "stem": "47 有關細胞毒殺過敏反應之敘述，下列何者錯誤？", "options": ["參與此類過敏反應的抗體是IgG 或IgM", "Rh 血型不合屬此類過敏反應", "參與此類過敏反應的細胞是吞噬細胞及殺手細胞", "紅血球、白血球、血小板的作用不受此類過敏反應影響\n代號：3102\n頁次：8－6"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-048", "year": 112, "session": "第一次", "no": 48, "stem": "48 有關器官移植前的組織配對，降低排斥反應之檢驗項目，不包含下列何者？", "options": ["ABO 及Rh 血型", "人類白血球抗原", "交叉配對試驗", "梅毒血清檢查"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-068", "year": 112, "session": "第一次", "no": 68, "stem": "68  一位18 歲女性主訴最近發現全身皮膚起紅疹、口腔潰瘍、關節疼痛、偶有頭痛，另血紅素及血小板\n\n  降低、抗核抗體升高，下列何者為其最可能之診斷？", "options": ["痛風性關節炎", "全身性紅斑性狼瘡", "後天免疫缺乏症候群", "類風濕性關節炎"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112110-102-0203-028", "year": 112, "session": "第二次", "no": 28, "stem": "28 有關心肌梗塞急性期的治療，下列敘述何者正確？①從鼻套管給10 L/min 氧氣 ②給予麻醉性止痛\n\n   劑止痛，如morphine ③給予血栓溶解劑治療 ④給予抗凝血劑治療 ⑤補充維生素K", "options": ["①②③", "①④⑤", "②③④", "③④⑤"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112110&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112110-102-0203-038", "year": 112, "session": "第二次", "no": 38, "stem": "38 王小姐最喜歡吃速食，餐餐吃都不膩，最近出現口炎、吞嚥困難且指甲萎縮變薄呈湯匙狀，醫師告知\n\n  為貧血，王小姐最有可能罹患那一種貧血？", "options": ["缺鐵性貧血", "惡性貧血", "葉酸缺乏性貧血", "再生不良性貧血"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112110&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112110-102-0203-048", "year": 112, "session": "第二次", "no": 48, "stem": "48 有關類風濕性關節炎藥物治療之敘述，下列何者錯誤？", "options": ["選擇性COX-2 抑制劑會抑制血小板凝集，延長出血時間", "aspirin 降低前列腺素合成，可減輕炎症及關節疼痛", "非固醇類抗炎藥（NSAIDs）是第一線用藥", "育齡婦女接受疾病調節抗風濕藥物治療時必須避孕\n代號：3102\n頁次：8－6"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112110&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112180-101-0103-023", "year": 112, "session": "第三次", "no": 23, "stem": "23 病人初次確診為缺鐵性貧血，醫囑須服用鐵劑，下列護理指導何者正確？", "options": ["可以正常喝茶", "鐵劑建議在兩餐之間空腹服用", "服用鐵劑時可以搭配牛奶一起使用", "服用鐵劑可以同時吃玉米"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "112180-101-0103-027", "year": 112, "session": "第三次", "no": 27, "stem": "27 病人剛接受骨髓移植2 週，主訴右上腹痛，評估有黃疸、腹水，下列何者是病人最有可能發生的問題？", "options": ["感染", "急性移植物抗宿主疾病（GVHD）", "肝靜脈阻塞（Veno-occlusive disease, VOD）", "腸阻塞"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "113100-102-0203-010", "year": 113, "session": "第二次", "no": 10, "stem": "10 預防全胃切除病人發生惡性貧血，可補充下列何種維生素？", "options": ["維生素A", "維生素B6", "維生素B12", "維生素K"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "113100-102-0203-021", "year": 113, "session": "第二次", "no": 21, "stem": "21 有關惡性貧血的敘述，下列何者錯誤？①與自體免疫有關 ②曾接受胃切除手術者較易罹患 ③可以進行\n  骨髓切片檢查確定診斷 ④須終生補充維生素B12", "options": ["④", "③", "②", "①"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "113100-102-0203-022", "year": 113, "session": "第二次", "no": 22, "stem": "22 有關何杰金氏淋巴瘤的敘述，下列何者正確？", "options": ["常見瀰漫不連續的淋巴結散布情形", "好發在中老年人較常見且男性為女性的2 倍", "常見發燒、盜汗、體重減輕等症狀", "常見骨髓侵犯"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "113100-102-0203-024", "year": 113, "session": "第二次", "no": 24, "stem": "24 陳小弟，15 歲，剛被診斷為急性白血病，醫師給予強度較強的化學治療，有關急性白血病治療完全緩解的\n  標準，下列何者錯誤？①骨髓內芽細胞（blast cell）＜5% ②周邊血液有芽細胞 ③無器官浸潤 ④造血\n  細胞接近正常值", "options": ["④", "③", "②", "①"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "113180-101-0103-024", "year": 113, "session": "第三次", "no": 24, "stem": "24 林小姐，45 歲，近三個月反覆發燒入院，診斷急性骨髓性白血病（AML），為了判定化學治療或骨髓移植的\n  治療效果，進行骨髓抽吸術，下列敘述何者正確？①術中不用麻醉 ②骨髓抽吸僅檢查白血球的數目、大小\n  ③可於後腸骨嵴處抽取 ④術後需使用砂袋加壓", "options": ["①②", "①③", "②④", "③④"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "113180-101-0103-026", "year": 113, "session": "第三次", "no": 26, "stem": "26 相較於何杰金氏病，有關非何杰金氏淋巴瘤之敘述，下列何者錯誤？", "options": ["常侵犯周邊多個淋巴結", "多呈現瀰漫性散布", "常出現發燒、夜間盜汗及體重減輕", "經常侵犯骨髓"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "113180-101-0103-030", "year": 113, "session": "第三次", "no": 30, "stem": "30 有關類風濕性關節炎臨床表徵之敘述，下列何者錯誤？①症狀通常兩側對稱性地發生 ②活動後有僵硬的\n  現象 ③通常侵犯大關節 ④可能造成腕隧道症候群", "options": ["①②", "①④", "②③", "③④"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "113180-101-0103-031", "year": 113, "session": "第三次", "no": 31, "stem": "31 全身性紅斑性狼瘡屬於下列那一型之過敏反應？", "options": ["第I 型立即性", "第II 型細胞毒性", "第III 型免疫複合物", "第IV 型延遲型"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "113180-101-0103-050", "year": 113, "session": "第三次", "no": 50, "stem": "50 有關各類型休克其病理機轉是因血管擴張引起分布性（distributive）或稱血管性（vasogenic）休克，下列\n  何者正確？①敗血性 ②低血容積性 ③過敏性 ④神經性 ⑤心因性", "options": ["①②③", "①③④", "②④⑤", "③④⑤"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "114100-102-0203-023", "year": 114, "session": "第二次", "no": 23, "stem": "23 王小華熱愛打籃球，最近剛被確診為血友病，下列護理指導何者不適當？", "options": ["不可自行服用阿斯匹靈（aspirin）止痛劑", "避免激烈及發生碰撞的活動", "頻繁地抽血監測凝血相關指數", "避免不必要的注射或手術\n代號：3102\n頁次：4－3"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "114100-102-0203-025", "year": 114, "session": "第二次", "no": 25, "stem": "25 王先生接受輸血治療過程中發生乾咳、血壓上升、嚴重呼吸困難等情形，下列何者為其最有可能發生的輸\n  血不良反應？", "options": ["循環過度負荷", "過敏反應", "熱原反應", "溶血反應"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "114170-101-0103-016", "year": 114, "session": "第三次", "no": 16, "stem": "16  38 歲孕齡婦女，診斷為下肢深部靜脈栓塞，接受抗凝血劑Heparin 注射治療，下列敘述何者最不適當？", "options": ["避免自行按摩腿部", "避免使用口服避孕藥", "避免食用深色蔬菜", "避免長期久坐"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114170&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "114170-101-0103-018", "year": 114, "session": "第三次", "no": 18, "stem": "18 病人因身體多處不明原因出血進行骨髓抽吸檢查，下列敘述何者最適當？①檢查目的在了解骨髓組織、造\n\n  血組織是否正常 ②可診斷是否為白血病 ③大多由脛骨進行抽取 ④大多需全身麻醉進行", "options": ["①②", "②③", "①④", "③④"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114170&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "114170-101-0103-020", "year": 114, "session": "第三次", "no": 20, "stem": "20 病人剛開始輸血20 mL 就發生皮膚癢、蕁麻疹、哮喘，最有可能發生下列那一種輸血反應？", "options": ["過敏反應", "熱原反應", "溶血反應", "細菌反應"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114170&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "114170-101-0103-029", "year": 114, "session": "第三次", "no": 29, "stem": "29 有關改善過敏反應的生活指導，下列敘述何者最適當？", "options": ["使用地氈及棉質窗簾", "避免使用除濕機及有濾網的空調", "避免用濕拖把及有集塵袋的吸塵器", "避免接觸二手菸與刺鼻味道的清潔劑"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114170&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "114170-101-0103-039", "year": 114, "session": "第三次", "no": 39, "stem": "39 有關急性腎盂腎炎之照護，下列敘述何者最適當？①紅血球沉降速率（ESR）數值會升高 ②症狀為無尿\n  及貧血 ③鼓勵病人多攝取酸灰性食物如乾梅或蔓越莓 ④鼓勵病人每4 小時排尿一次", "options": ["①④", "①③", "②③", "②④\n代號：3101\n頁次：4－4"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114170&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "115100-102-0203-031", "year": 115, "session": "第二次", "no": 31, "stem": "31 下列何者不是愛滋病人服用高效能抗反轉錄病毒治療（俗稱雞尾酒療法）之副作用？", "options": ["心血管疾病", "糖尿病", "骨質疏鬆", "高密度膽固醇血症"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=115100&c=102&s=0203&q=1", "status": "needs_visual_review"}], "6": [{"id": "106030-106-0503-041", "year": 106, "session": "第一次", "no": 41, "stem": "41 有關乳癌之敘述，下列何者錯誤？", "options": ["偏好高脂肪食物者罹患率較高", "乳癌腫塊最常發現於乳房外上方1/4 處", "乳癌病人的癌胚抗原（CEA）值為介於1.0～3.0 ng/mL", "乳癌細胞通常會侵犯淋巴系統"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-034", "year": 106, "session": "第二次", "no": 34, "stem": "34 有關乳癌病人荷爾蒙治療之敘述，下列何者錯誤？", "options": ["治療副作用有倦怠、皮膚癢、噁心嘔吐等", "停經後婦女比停經前婦女的治療效果好", "Tamoxifen 是轉移性乳癌第一線用藥，一般療程為5 年", "體內動情素受體和黃體素受體含量越低，治療反應越好"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-061", "year": 106, "session": "第二次", "no": 61, "stem": "61 有關睪丸癌最主要的危險因子，下列何者正確？", "options": ["隱睪症", "精索曲張", "長期接觸金屬物", "無精蟲症"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-034", "year": 106, "session": "第二次", "no": 34, "stem": "34  有關子宮頸癌行後荷式（after loading）體內放射線治療之照護措施，下列何者錯誤？", "options": ["穿鉛衣，可降低接觸輻射線的暴露量", "若放射源脫落，用長柄鑷子夾起再放入鉛桶中", "病人尿液要放入鉛桶，待過了半衰期再處理", "採集中護理，以減少暴露放射線的危險"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-037", "year": 107, "session": "第一次", "no": 37, "stem": "37 有關乳癌手術後復健運動之敘述，下列何者正確？", "options": ["在引流管拔除前，不能做復健運動，以免牽扯傷口", "術後2 天後可執行手肘以下的關節運動", "術後4～7 天才可執行刷牙、洗臉之一般日常活動", "術後1 週可游泳\n代號：3106\n頁次：8－5"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107110-106-0503-041", "year": 107, "session": "第二次", "no": 41, "stem": "41 王小姐罹患乳癌第四期，醫生建議放射線合併化學治療，此種放射線治療是屬於何種治療方式？", "options": ["根除性", "輔助性", "誘導性", "預防性"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-036", "year": 108, "session": "第一次", "no": 36, "stem": "36 與乳癌有關的腫瘤標記，下列何者正確？", "options": ["carcinoembryonic antigen（CEA）", "prostatic specific antigen（PSA）", "alpha fetoprotein（AFP）", "alkaline phosphatase"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-045", "year": 108, "session": "第一次", "no": 45, "stem": "45 有關生殖器疱疹的敘述，下列何者錯誤？", "options": ["為性交傳染", "教導病人避免擠壓患部水疱", "發病後7～10 天避免與他人親密性接觸", "由帶狀水痘病毒感染所引起"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108110-106-0503-007", "year": 108, "session": "第二次", "no": 7, "stem": "7 有關腦瘤之敘述，下列何者正確？①腦膜瘤好發於男性 ②續發性腦瘤常見於肺癌或乳癌病人\n  ③突然的發作抽搐是腦瘤的明顯指標 ④星狀細胞瘤好發於女性", "options": ["①②", "①③", "②③", "②④"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108110-106-0503-036", "year": 108, "session": "第二次", "no": 36, "stem": "36 有關乳癌轉移壓迫脊髓最常見之部位，下列何者正確？", "options": ["頸椎", "胸椎", "腰椎", "薦椎"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-076", "year": 109, "session": "第一次", "no": 76, "stem": "76 乳癌病人接受化學治療效果不佳，病人主訴：「我希望能活到女兒結婚有個依靠，我就可以放心離\n   開，就讓我活到那時候吧！」請問病人是處於Kubler-Ross 心理反應的那一階段？", "options": ["否認期", "磋商期", "憤怒期", "接受期"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-077", "year": 109, "session": "第一次", "no": 77, "stem": "77 乳癌病人手術後的病理報告：乳房惡性腫瘤為3 公分，腋下有2 顆淋巴結轉移。依癌症TNM 分期，\n  下列何者正確？", "options": ["cT2N1M0", "cT2N1Mx", "pT2N1M0", "pT2N1Mx"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-040", "year": 110, "session": "第一次", "no": 40, "stem": "40 有關預防乳癌病人術後淋巴水腫的照護，下列敘述何者正確？", "options": ["術後第二天才可以操作手指屈曲和腕部伸展運動", "爬牆和轉繩運動在有引流管時，就要開始做", "側臥時，健臂在上，枕頭夾於腋下到臀部，並將手墊高", "臥床時，用枕頭將肩部與患臂墊高，使手腕比手肘高，手肘比肩膀高"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-047", "year": 110, "session": "第一次", "no": 47, "stem": "47 有關乳癌的敘述，下列何者錯誤？", "options": ["約5～10%乳癌與遺傳有關", "多數乳癌腫塊會有疼痛感", "乳房自我檢查不能檢測到所有的腫瘤", "最常發生部位為乳房外上四分之一"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111030-104-0303-042", "year": 111, "session": "第一次", "no": 42, "stem": "42 有關乳癌症狀與疾病分期之敘述，下列何者正確？", "options": ["好發部位在乳房的內上1/4 處", "T2N1M0 屬於癌症分期的第三期", "最常見的症狀為疼痛性腫塊", "乳頭下腫塊會造成乳頭回縮或高低不一"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-037", "year": 112, "session": "第一次", "no": 37, "stem": "37  周女士，52 歲，本身有高血壓及乳癌家族史，有抽菸，在一次回診時表示自己年紀越來越大，很擔\n\n  心會跟媽媽一樣罹癌，下列建議何者錯誤？", "options": ["不用過度擔心，若自覺乳房有異狀再做乳房攝影", "鼓勵戒菸、轉介戒菸門診", "將運動融入生活，可以走樓梯代替搭電梯等", "適度日曬，促進維生素D 合成"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112110-102-0203-034", "year": 112, "session": "第二次", "no": 34, "stem": "34 張小姐，42 歲，診斷為乳癌第二期，日前進行癌症治療，有關腫瘤標記之敘述，下列何者錯誤？", "options": ["腫瘤標記為一系列與癌症相關、可測量之特殊化學物質", "CA-15-3 為早期鑑別診斷乳癌發生的標記", "腫瘤標記不建議用於篩檢、輔助診斷或預測預後", "對於較早期之癌症敏感度很低"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112110&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112180-101-0103-024", "year": 112, "session": "第三次", "no": 24, "stem": "24 乳腺癌病人出現意識混亂、嗜睡、虛弱、心律不整、嘔吐及便秘，下列何者為其最可能發生的癌症合併症？", "options": ["腫瘤溶解症候群", "上腔靜脈症候群", "脊髓壓迫", "高血鈣症"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "113100-102-0203-033", "year": 113, "session": "第二次", "no": 33, "stem": "33 有關乳癌病人荷爾蒙治療之敘述，下列何者錯誤？", "options": ["Letrozole（Femara）是轉移性乳癌第一線用藥，需服用2～5 年", "停經後婦女的荷爾蒙治療效果比停經前婦女好", "雌性素受體（ER）或黃體素受體（PR）呈陽性者，治療效果較好", "抗雌性素治療會有骨質疏鬆副作用，需定期做骨質密度檢查"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "113180-101-0103-022", "year": 113, "session": "第三次", "no": 22, "stem": "22 一位正在接受胸壁放射治療的復發性乳癌病人表示：「吞嚥時感到疼痛，胸口有灼熱及緊繃感」。下列何者\n  是病人因放射線治療導致最可能的結果？", "options": ["肺炎", "食道裂孔疝氣", "胃炎", "食道炎"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "114100-102-0203-010", "year": 114, "session": "第二次", "no": 10, "stem": "10 王先生，170 cm，88 Kg，從事搬運工，因腹股溝疝氣接受手術治療，有關疝氣手術後護理指導，下列何者\n  正確？①傷口處熱敷，以減輕疼痛與腫脹 ②不需要特別減重以免營養不良 ③陰囊應給與支托後再下床\n  ④平時應多吃蔬果以預防便秘 ⑤出院後可立即上班從事搬運工作", "options": ["①②", "②③", "③④", "④⑤"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "115100-102-0203-026", "year": 115, "session": "第二次", "no": 26, "stem": "26 有關乳癌之相關敘述，下列何者最不適當？", "options": ["可能出現佩吉特氏病（Paget’s disease）", "乳癌與EGFR 基因的關聯性最高", "改良式根除性乳房切除術適用於沒有胸大肌侵犯的病人", "採用抗動情素劑（tamoxifen）的病人需注意臉部潮紅、噁心副作用"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=115100&c=102&s=0203&q=1", "status": "needs_visual_review"}], "7": [{"id": "106030-106-0503-022", "year": 106, "session": "第一次", "no": 22, "stem": "22 有關急性中耳炎感染途徑之敘述，下列何者錯誤？", "options": ["經耳咽管感染", "經外耳道感染", "經血行感染", "經淋巴感染"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-021", "year": 106, "session": "第二次", "no": 21, "stem": "21 有關白內障症狀之敘述，下列何者錯誤？", "options": ["視力減退", "眼睛疼痛", "畏光", "單眼複視"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-024", "year": 106, "session": "第二次", "no": 24, "stem": "24 有關喉癌之敘述，下列何者錯誤？", "options": ["喉癌大多屬鱗狀細胞癌", "長期抽菸為喉癌致病因素", "聲音嘶啞為喉癌早期症狀", "聲門上喉癌較少發生淋巴轉移\n代號：3106\n頁次：6－3"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-023", "year": 106, "session": "第二次", "no": 23, "stem": "23 有關鼻竇炎護理指導之敘述，下列何者錯誤？", "options": ["告訴病人戒菸", "鼻滴劑使用後，4 小時內症狀未改善可再使用", "慢性鼻竇炎的抗生素需持續使用至少7 天", "攝取足夠液體"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-021", "year": 107, "session": "第一次", "no": 21, "stem": "21 有關視網膜剝離時立即處理之敘述，下列何者錯誤？", "options": ["坐下休息", "雙眼蓋上眼罩", "勿隨意移動頭部", "禁止用力"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-022", "year": 107, "session": "第一次", "no": 22, "stem": "22 有關使用音叉評估聽力喪失之敘述，下列何者錯誤？", "options": ["目的在區別傳導性聽力或感覺神經性聽力喪失", "避免強烈敲擊音叉", "韋伯氏試驗（Weber’s Test）結果：有感覺神經性聽覺喪失的患耳聽到的聲音會比較大", "任內氏試驗（Rinne’s Test）結果：有傳導性聽覺喪失的患耳為陰性反應"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-024", "year": 107, "session": "第一次", "no": 24, "stem": "24 下列何者不是接受扁桃腺切除術之禁忌？", "options": ["急性扁桃腺炎一年發作7 次以上", "扁桃腺急性發炎期間", "肺結核活動期間病人", "血液惡性疾病病人"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107110-106-0503-022", "year": 107, "session": "第二次", "no": 22, "stem": "22 有關青光眼藥物作用的敘述，下列何者正確？", "options": ["縮瞳劑可抑制房水液排出", "β腎上腺素阻斷劑可抑制房水液生成", "乙醯膽鹼酶抑制劑可抑制房水液生成", "前列腺素致效劑可抑制房水液生成"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107110-106-0503-025", "year": 107, "session": "第二次", "no": 25, "stem": "25 有關白內障摘除術後預防眼壓上升的護理指導，下列何者正確？", "options": ["可以彎腰撿起掉在地上的東西", "避免睡向手術側", "可採俯臥睡姿", "術後第二天可以咳嗽或用力擤鼻涕\n代號：3106\n頁次：6－3"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-021", "year": 108, "session": "第一次", "no": 21, "stem": "21 與引起聽力問題有關之疾病，下列何者最不可能？", "options": ["甲狀腺功能亢進", "高血壓", "糖尿病", "頭部外傷"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-022", "year": 108, "session": "第一次", "no": 22, "stem": "22 有關視網膜剝離手術後病人護理措施之敘述，下列何者錯誤？", "options": ["術後即採俯臥4～5 天", "覆眼敷料有滲出液為正常的現象", "術後2～3 週內避免閱讀", "若近視度數改變，應等3 個月後才更換眼鏡"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-023", "year": 108, "session": "第一次", "no": 23, "stem": "23 有關鼻竇炎之敘述，下列何者錯誤？", "options": ["鼻竇炎最常出現在上頷竇", "鼻竇炎若未治療，可能出現腦膜炎、腦膿瘍等合併症", "慢性鼻竇炎為鼻竇炎症狀持續2～3 個月以上", "慢性鼻竇炎症狀包括鼻塞、高燒、顏面疼痛等症狀"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-024", "year": 108, "session": "第一次", "no": 24, "stem": "24 有關喉癌手術後發聲及吞嚥功能改變之敘述，下列何者錯誤？", "options": ["聲門上喉切除術後2 週內可能會出現吞嚥困難", "聲門上喉切除術後無法發聲", "部分喉切除術保留一側聲帶，術後可能聲音沙啞", "部分喉切除術後可以正常吞嚥"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108110-106-0503-008", "year": 108, "session": "第二次", "no": 8, "stem": "8 有關青光眼藥物治療作用之敘述，下列何者錯誤？", "options": ["可使用縮瞳劑", "pilocarpine 可促進房水流入許萊姆氏管", "timolol 可減少房水分泌", "diamox 可促進房水排出"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108110-106-0503-019", "year": 108, "session": "第二次", "no": 19, "stem": "19 有關白內障治療方式之敘述，下列何者錯誤？", "options": ["白內障無有效治療的藥物", "囊內摘除術易造成網膜剝離", "晶體乳化法為囊外摘除術", "人工水晶體可在晶體乳化術後一個月植入"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108110-106-0503-021", "year": 108, "session": "第二次", "no": 21, "stem": "21 有關喉癌的臨床表徵，下列何者正確？", "options": ["外生性喉癌易發生頸部淋巴轉移，造成頸部淋巴結腫大", "外生性喉癌會有聲音嘶啞、喉部異物感", "內生性喉癌早期症狀為吞嚥時發生喉痛、灼熱感", "內生性喉癌好發於喉部真聲帶以外之其他部位"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-023", "year": 109, "session": "第一次", "no": 23, "stem": "23 有關扁桃腺炎病人接受扁桃腺切除術之敘述，下列何者錯誤？", "options": ["適用於反覆慢性扁桃腺感染病人", "不適用於有血液惡性疾病的扁桃腺炎病人", "術後病人經常有吞嚥動作是正常的", "術後醫囑可以開始進食時，須先進冷食"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-024", "year": 109, "session": "第一次", "no": 24, "stem": "24 有關喉癌病人接受全喉切除術後之護理處置，下列何者錯誤？", "options": ["維持呼吸道通暢為首要目標", "協助採取側臥式", "當病人坐起時需以手支托後頸", "傷口癒合前須由鼻胃管補充營養"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-022", "year": 109, "session": "第二次", "no": 22, "stem": "22 有關聽力喪失可聽見的音量敘述，下列何者錯誤？", "options": ["可聽見在25 分貝內的音量，聽力正常", "只能聽見30 分貝以上的音量，聽力為輕度受損", "只能聽見60 分貝以上的音量，聽力為重度受損", "只能聽見90 分貝以上的音量，聽力為極重度受損"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-023", "year": 109, "session": "第二次", "no": 23, "stem": "23 有關鼻竇炎術後的護理措施，下列何者錯誤？", "options": ["採平躺臥姿", "冰敷鼻子與臉頰", "若有引流物，由口吐出，不要擤鼻子", "以棉籤適度清潔口腔或漱口"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-024", "year": 109, "session": "第二次", "no": 24, "stem": "24 有關美尼爾氏症之敘述，下列何者正確？①可能原因是外耳淋巴液過多 ②症狀為雙側傳導性聽力減退\n  ③使用血管擴張劑減輕耳鳴症狀 ④藥物治療無效時，可採迷路切除術", "options": ["①②", "①③", "②④", "③④"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-025", "year": 109, "session": "第二次", "no": 25, "stem": "25 有關白內障之敘述，下列何者錯誤？", "options": ["眼睛水晶體發生混濁", "瞳孔呈乳白色", "好發於兩側", "約95%發生於高度近視者"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-055", "year": 109, "session": "第二次", "no": 55, "stem": "55 有關護理師給予氣切造口（tracheostomy）病人抽痰時，下列措施何者最重要？", "options": ["執行氣切造口護理", "聽診呼吸音", "給予抗焦慮劑", "評估血氧的變化\n代號：3106\n頁次：6－5"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-022", "year": 110, "session": "第一次", "no": 22, "stem": "22 為了避免白內障手術病人植入之水晶體移位，返家後活動限制的護理指導，下列何者錯誤？", "options": ["不可提重物", "不可彎腰", "不可咳嗽", "不可深呼吸"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-025", "year": 110, "session": "第一次", "no": 25, "stem": "25 有關急性中耳炎之敘述，下列何者正確？", "options": ["外耳道會有過多的耳垢", "鼓膜可能出現發亮的珍珠灰色", "嚴重時，將導致傳導性聽力喪失", "持續服用抗生素至發燒症狀緩解"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-022", "year": 110, "session": "第二次", "no": 22, "stem": "22 有關白內障症狀的敘述，下列何者錯誤？", "options": ["畏光", "視力減退", "眼痛", "瞳孔變為白色"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-024", "year": 110, "session": "第二次", "no": 24, "stem": "24 有關視網膜剝離病人的術後護理措施，下列何者錯誤？", "options": ["應蓋上敷料及眼罩並觀察敷料是否有滲出液", "術後一週內應避免眼球快速運動", "手術時玻璃體腔注入氣體時，術後應採仰臥", "若有噁心及嘔吐情形，應禁食到無胃部不適為止"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-025", "year": 110, "session": "第二次", "no": 25, "stem": "25 有關感覺神經性聽力喪失的敘述，下列何者正確？", "options": ["在噪音中聽力佳", "韋伯氏測驗（Weber’s test）結果患側聽到比較大的聲音", "任內氏測驗（Rinne’s test）結果空氣傳導時間比骨傳導時間長", "外耳道或鼓膜異常\n代號：3104\n頁次：6－3"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-040", "year": 110, "session": "第二次", "no": 40, "stem": "40 有關瀕死病人護理的敘述，下列何者正確？①出現瀕死前的嘎嘎聲是因為喉嚨有痰，要給予抽痰\n  ②肛門附近周圍皮膚傷口可使用氧化鋅 ③要鼓勵病人進食，以增加舒適感 ④瀕死病人對刺激無\n  反應時，其聽力也會喪失 ⑤意識不清病人宜採側臥，以利分泌物流出", "options": ["①②", "①④", "②⑤", "③⑤"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111030-104-0303-022", "year": 111, "session": "第一次", "no": 22, "stem": "22 有關青光眼病人之護理措施，下列何者正確？", "options": ["眼內壓上升超過正常值且造成視神經受損，稱為青光眼", "準備病人接受晶狀體植入", "熬夜不會影響眼壓", "指導病人術後臥向手術側"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111030-104-0303-023", "year": 111, "session": "第一次", "no": 23, "stem": "23 有關中耳炎手術病人之術後護理指導，下列何者錯誤？", "options": ["手術後要觀察有無切斷顏面神經的合併症", "病人應採用軟質飲食", "禁做會阻塞耳咽管的伐氏操作法（Valsalva’s Maneuver）", "勿用力擤鼻子、用力咳嗽或打噴嚏"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111030-104-0303-025", "year": 111, "session": "第一次", "no": 25, "stem": "25 有關聽力喪失病人的護理指導，下列何者錯誤？", "options": ["與別人溝通時，等待對方先開口", "採用適當的位置，使說話者面部採光良好", "要求對方先說明主題，當改變話題時先通知", "家中電話加裝擴音器，或家中電鈴加裝閃光\n代號：3104\n頁次：6－3"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-022", "year": 111, "session": "第二次", "no": 22, "stem": "22 有關白內障的晶體乳化法手術的敘述，下列何者錯誤？", "options": ["需等晶狀體成熟後才執行手術", "用超音波將晶體核震碎後取出", "可縮小傷口至0.3 公分", "手術中同時植入人工水晶體"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-025", "year": 111, "session": "第二次", "no": 25, "stem": "25 有關扁桃腺炎的處置，下列何者錯誤？", "options": ["急性發炎時行扁桃腺切除術", "用溫食鹽水漱口", "冰敷可以緩解咽喉部疼痛", "發燒症狀消退後，抗生素仍需使用48～72 小時\n代號：3104\n頁次：6－3"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-021", "year": 112, "session": "第一次", "no": 21, "stem": "21 白內障可能出現的症狀，下列何者正確？①眼睛痛 ②眼睛紅 ③視力模糊 ④瞳孔變灰或白色", "options": ["①②", "①④", "②③", "③④"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-024", "year": 112, "session": "第一次", "no": 24, "stem": "24 有關喉癌病人接受全喉切除術的敘述，下列何者正確？", "options": ["氣管造口為暫時性的", "術後嗅覺喪失，但不影響味覺", "適合第一、二期喉癌病人", "術後仍可恢復正常的發聲功能"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112110-102-0203-021", "year": 112, "session": "第二次", "no": 21, "stem": "21 有關急性鼻竇炎的處置，下列何者錯誤？", "options": ["抗生素至少要連續使用7 天以上", "可以使用解熱鎮痛劑緩解發燒及疼痛", "鼻噴劑可以隨時使用以改善鼻塞症狀", "使用蒸氣吸入可以促進鼻竇引流"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112110&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112110-102-0203-023", "year": 112, "session": "第二次", "no": 23, "stem": "23 有關喉癌術後放置永久性喉切除管（Laryngectomy tube）病人的出院護理指導，下列何者不適宜？", "options": ["每天以濕毛巾清潔造口周圍皮膚", "坐起或翻身時需以手托後頸，避免頸部過度伸張", "咳嗽或打噴嚏時，用手帕蓋住造口處，另一手掩住嘴巴", "鼓勵採用固定於牆上的壁掛式淋浴設備"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112110&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112180-101-0103-014", "year": 112, "session": "第三次", "no": 14, "stem": "14 下列何者是視網膜剝離最主要的疾病機轉？", "options": ["視網膜喪失營養供應", "水晶體混濁", "眼內壓上升", "眼角膜受損"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "112180-101-0103-015", "year": 112, "session": "第三次", "no": 15, "stem": "15 有關美尼爾氏症（Meniere’s syndrome）之敘述，下列何者正確？①內耳淋巴水腫引起 ②眩暈及耳朵疼痛\n  是典型症狀 ③可能導致單側傳導性聽力喪失 ④耳鳴是典型症狀", "options": ["①②", "①④", "②③", "③④"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "112180-101-0103-017", "year": 112, "session": "第三次", "no": 17, "stem": "17 有關慢性鼻竇炎的原因，下列何者正確？", "options": ["由於急性鼻竇炎未完全治療所致", "與鼻息肉生成無關", "常由流行性感冒嗜血桿菌引起", "常見的感染致病菌為好氧菌"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "112180-101-0103-036", "year": 112, "session": "第三次", "no": 36, "stem": "36 有關執行氣切造口術病人抽痰的敘述，下列何者不適當？", "options": ["抽吸壓力120～150 mmHg", "抽吸前給予氧氣吸入30～60 秒", "抽痰管插入深度15～20 公分", "抽痰完成後聽診呼吸音"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "113100-102-0203-013", "year": 113, "session": "第二次", "no": 13, "stem": "13 病人接受白內障囊外摘除術後之護理指導，下列何者最適當？ ①用力咳嗽 ②彎腰洗頭 ③預防便秘\n  ④避免提重物", "options": ["①②", "①③", "②④", "③④"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "113100-102-0203-015", "year": 113, "session": "第二次", "no": 15, "stem": "15 有關視網膜剝離的緊急處理，下列何者錯誤？", "options": ["立刻臥床", "單眼蓋上眼罩", "勿隨意移動頭部", "減少焦慮"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "114100-102-0203-014", "year": 114, "session": "第二次", "no": 14, "stem": "14 下列何者為白內障最主要的病變構造？", "options": ["角膜", "水晶體", "鞏膜", "視神經"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "114100-102-0203-015", "year": 114, "session": "第二次", "no": 15, "stem": "15 病人左耳聽力正常，右耳有聽力障礙，以韋伯試驗（Weber test）發現右耳比較大聲，再以任內試驗（Rinne\n  test）發現左耳空氣傳導＞骨傳導、右耳空氣傳導≦骨傳導，下列何者是病人右耳最可能的病變位置？\n  ①外耳 ②中耳 ③內耳 ④耳蝸神經", "options": ["①②", "①③", "②④", "③④"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "114170-101-0103-015", "year": 114, "session": "第三次", "no": 15, "stem": "15 有關扁桃腺炎，下列敘述何者最不適當？", "options": ["急性扁桃腺炎以鏈球菌感染最常見", "會有發燒、喉嚨痛及吞嚥時疼痛的症狀", "急性發炎期是行扁桃腺切除術的最佳時機", "扁桃腺切除術後避免用力咳嗽以預防出血"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114170&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "115100-102-0203-013", "year": 115, "session": "第二次", "no": 13, "stem": "13 有關病人接受白內障手術後1 個月內之護理指導，下列何者不適當？", "options": ["避免彎腰洗頭", "採趴睡或睡向患側", "避免搭飛機出國旅遊", "外出戴太陽眼鏡"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=115100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "115100-102-0203-015", "year": 115, "session": "第二次", "no": 15, "stem": "15 有關喉癌病人行全喉切除術後之敘述，下列何者正確？", "options": ["永久性氣切造口會乾燥，可以直接滴入生理食鹽水", "嗅覺和味覺不受影響，所以不會影響病人的食慾", "經由語言復健可以訓練病人以食道語與他人溝通", "為避免身體心像紊亂建議用防水敷料覆蓋氣切口"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=115100&c=102&s=0203&q=1", "status": "needs_visual_review"}], "8": [{"id": "106030-106-0503-043", "year": 106, "session": "第一次", "no": 43, "stem": "43 有關三度燒傷傷口的處置，下列何者錯誤？", "options": ["可用水療來除去壞死組織、減少菌落，避免感染", "可用生物敷料長期覆蓋傷口，保護皮膚並減輕疼痛感，不需要進行植皮手術", "無法自行脫落或感染的壞死組織，可用擴創術來移除", "當環狀肢體因燒傷焦痂限制血液循環時，則須做焦痂切開術，避免組織缺血造成壞死"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-043", "year": 106, "session": "第二次", "no": 43, "stem": "43 有關嚴重燒傷病人急性期的疼痛處置，下列何者最適當？", "options": ["morphine 4 mg IV every 5 minutes", "morphine 10 mg IM q4H", "meperidine 50 mg PO q4H", "fentanyl citrate（Duragesic）75 mcg patch q3D"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-045", "year": 106, "session": "第二次", "no": 45, "stem": "45 有關燒傷傷口臨床表徵的敘述，下列何者正確？", "options": ["表淺部分皮層燒傷部位會有水泡形成，中重度疼痛", "四度燒傷傷口呈現乾燥、焦黑、中重度疼痛", "深二度燒傷傷口皮膚呈現粉紅色、紅腫、劇烈疼痛", "三度燒傷傷口皮膚乾燥、受壓不會變蒼白、皮革狀焦痂"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-044", "year": 106, "session": "第二次", "no": 44, "stem": "44 下列那位燒傷病人最容易發生腔室症候群？", "options": ["25 歲右上肢有環形燒傷（circumferential burns）病人", "7 歲左右耳燒傷病人", "55 歲頸部電燒傷病人", "15 歲右足化學燒傷病人"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-046", "year": 106, "session": "第二次", "no": 46, "stem": "46 有關燒傷病人植皮後的出院護理指導，下列何者正確？", "options": ["燒傷疤痕不可按摩", "燒傷部位避免直接陽光照射", "已癒合傷口不可以塗抹乳液", "多臥床休息，燒傷部位予以制動\n代號：3106\n頁次：8－6"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-044", "year": 107, "session": "第一次", "no": 44, "stem": "44  王先生25 歲燒傷入院，全身有20%的部分皮層燒傷，燒傷部位位於雙下肢，其燒傷嚴重度，下列何\n\n  者正確？", "options": ["輕度燒傷", "中度燒傷", "嚴重燒傷", "大面積燒傷"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-045", "year": 107, "session": "第一次", "no": 45, "stem": "45 有關燒傷病人植皮前後之護理措施，下列何者錯誤？", "options": ["植皮後應密切監測傷口滲液的性質以及有無出血", "供皮區在取皮後應壓迫4～6 小時，以減少滲血", "供皮區在癒合後，可使用乳液減少搔癢", "傷口應多接觸日照，以利維生素D 形成"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107110-106-0503-047", "year": 107, "session": "第二次", "no": 47, "stem": "47 有關不同燒傷深度的傷口癒合情形之敘述，下列何者錯誤？", "options": ["一度燒傷的傷口，可自行癒合，不會有疤痕", "二度燒傷的傷口，可自行癒合，不會有疤痕", "三度燒傷的傷口，不會自行癒合，需要皮膚移植", "四度燒傷的傷口，不會自行癒合，需要皮膚或皮瓣移植"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107110-106-0503-048", "year": 107, "session": "第二次", "no": 48, "stem": "48 有關大面積重度燒傷初期（48 小時內）對於腎臟系統的影響，下列何者錯誤？", "options": ["組織破壞釋出大量肌球蛋白，引起急性腎小管壞死", "腎絲球過濾率增加，引起急性腎衰竭", "少尿、尿比重增加", "必須補充水分來防止永久性的腎損傷"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-043", "year": 108, "session": "第一次", "no": 43, "stem": "43 有關燒傷病人達到體液復甦目標之指標，下列何者正確？", "options": ["血比容（Hematocrit）60%", "脈搏130 次／分", "尿比重1.035", "尿量每小時50 毫升"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-046", "year": 108, "session": "第一次", "no": 46, "stem": "46 有關燒傷病人接受自體移植後出院之護理指導，下列何者錯誤？", "options": ["鼓勵全範圍關節運動", "鼓勵植皮部位多曬太陽，以促進黑色素形成", "燒傷部位穿著壓力衣並使用潤膚乳液", "燒傷部位可使用副木等支持物以避免關節攣縮"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108110-106-0503-041", "year": 108, "session": "第二次", "no": 41, "stem": "41 有關燒傷病人給與靜脈滴注「H2 受體阻斷劑」類藥物（如tagamet）之目的，下列何者正確？", "options": ["刺激腸蠕動", "預防低血容積", "預防壓力性潰瘍", "預防腎損傷"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108110-106-0503-042", "year": 108, "session": "第二次", "no": 42, "stem": "42 有關燒傷水療法之敘述，下列何者錯誤？", "options": ["水療池的水溫通常維持在26.6～29.4℃", "水療池中可加入Beta-iodine，以抑制細菌生長", "水療池中可加入食鹽，以補充流失的體液", "水療法可以降低感染以及減少瘢痕形成"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108110-106-0503-045", "year": 108, "session": "第二次", "no": 45, "stem": "45 有關燒傷病人的緊急處理措施5 步驟之敘述，下列何者錯誤？", "options": ["沖：以流動的冷水沖患部", "脫：用剪刀移除衣物，若衣物與傷口沾黏，勿強行脫除", "泡：將患部泡在冰水中降溫，將餘熱去除減輕疼痛感", "蓋：以乾淨的衣物、毛毯、紗布等覆蓋，保存體溫且避免污染傷口"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-041", "year": 109, "session": "第一次", "no": 41, "stem": "41 有關大面積重度燒傷初期（48 小時內），對於心臟血管系統造成的影響，下列何者錯誤？", "options": ["中心靜脈壓升高", "心輸出量減少", "全身性水腫", "脈搏淺快"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-045", "year": 109, "session": "第二次", "no": 45, "stem": "45 有關使用Braden scale 評估壓傷危險因子和處置之敘述，下列何者正確？", "options": ["滿分為24 分，分數越高表示皮膚風險越大", "13 分代表中等危險，需每2 小時翻身及評估皮膚", "依據摩擦力和剪力程度決定是否需使用氣墊床", "壓傷危險分級是依據三大層面總和分數做判定"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-046", "year": 109, "session": "第二次", "no": 46, "stem": "46 針對右髖關節嚴重燒傷病人，為維持其關節最大功能之姿位，下列何者正確？", "options": ["髖關節維持屈曲30 度", "髖關節屈曲0 度，仰臥腿伸展", "膝關節屈曲30 度", "大腿內收"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-048", "year": 109, "session": "第二次", "no": 48, "stem": "48 成年病人燒傷面積：軀幹正面皮膚發紅且有大片水泡、右上肢前面皮膚呈現灰白色以及有水泡。依九\n  的法則計算其燒傷總體表面積，下列何者正確？", "options": ["18%", "22.5%", "27%", "40.5%"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-006", "year": 110, "session": "第一次", "no": 6, "stem": "6 協助昏迷病人由側臥翻成平躺時，須注意下列那一個部位是否有壓傷形成？", "options": ["枕骨", "尾椎骨", "足跟", "踝部"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-045", "year": 110, "session": "第一次", "no": 45, "stem": "45 有關化學物質燒傷導致皮下組織損傷的處置，下列何者錯誤？", "options": ["休克期應預防低血鈉及代謝性酸中毒", "利尿期應預防低血鉀及代謝性酸中毒", "在燒傷現場應先沖洗再送醫", "恢復期應預防急性腎衰竭"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-046", "year": 110, "session": "第一次", "no": 46, "stem": "46 有關燒傷病人居家照護的護理指導，下列何者錯誤？", "options": ["每天評估傷口狀況並換藥，有感染症狀需就醫", "已癒合傷口可塗抹乳液等潤膚劑，避免乾燥", "避免按摩疤痕，減少疤痕增生", "持續執行肢體復健運動，避免肢體攣縮"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-047", "year": 110, "session": "第二次", "no": 47, "stem": "47 有關燒傷病人敷料應用的敘述，下列何者錯誤？", "options": ["1% Silver Sulfadiazine 不會造成酸鹼與電解質不平衡", "0.5% Silver Nitrate 會造成高血鈉，應密切監測電解質", "Gentamycin Sulfate 適用於臉部傷口，應密切監測腎功能變化", "使用1% Silver Sulfadiazine 應觀察有無白血球數目減少"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111030-104-0303-047", "year": 111, "session": "第一次", "no": 47, "stem": "47 有關燒傷深度的敘述，下列何者錯誤？", "options": ["一度燒傷是指表皮受到損害，會有疼痛感", "二度燒傷是指真皮層受到損傷，會有劇烈疼痛", "三度燒傷是指全皮層的損傷，會有劇烈疼痛", "四度燒傷是指全皮層、肌肉和骨骼的損傷，沒有疼痛感"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-044", "year": 111, "session": "第二次", "no": 44, "stem": "44  18 歲女大生因玩煙火，導致左手有部分燒痂到急診求診，對燒傷部位的立即護理處置，下列何者正\n  確？", "options": ["將左手浸生理食鹽水中", "抬高左手減輕水腫", "局部用藥減輕感染", "手術切開水泡和清創"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-045", "year": 111, "session": "第二次", "no": 45, "stem": "45 皮膚表皮破皮並看得到皮下脂肪組織，且傷口出現黏液或滲出物，可能為第幾期壓傷？", "options": ["第一期", "第二期", "第三期", "無法分期"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-047", "year": 111, "session": "第二次", "no": 47, "stem": "47 有關燒傷的病生理變化，下列何者錯誤？", "options": ["燒傷48 小時內，應密切監測鉀離子，以避免高血鉀影響心臟功能及危及生命", "燒傷初期病人會出現少尿、尿液濃縮及尿比重增加", "大範圍燒傷面積病人常在燒傷後72 小時出現壓力性潰瘍", "在燒傷後48～72 小時，病人會出現血比容升高、血鈉上升以及尿量減少"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-050", "year": 111, "session": "第二次", "no": 50, "stem": "50 接觸性皮膚炎病人因搔癢不適至門診治療，下列護理指導何者錯誤？", "options": ["屬於過敏反應", "避免接觸已知的過敏原", "經常用肥皂清潔以緩解過敏症狀", "服用抗組織胺類藥物時須避免開車"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-044", "year": 112, "session": "第一次", "no": 44, "stem": "44 王同學騎機車不慎與汽車擦撞引發機車起火，右小腿外側有15 公分×7.5 公分的皮膚受損，診斷為深\n\n  二度燒傷。下列臨床表徵何者正確？①皮膚變紅無水泡 ②皮膚呈灰白色有水泡 ③劇烈疼痛感\n\n  ④汗腺及毛囊完整 ⑤表皮及真皮層受損", "options": ["①③④", "①④⑤", "②③⑤", "②④⑤"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112110-102-0203-045", "year": 112, "session": "第二次", "no": 45, "stem": "45 有關電燒傷所造成的身體損傷，下列敘述何者正確？", "options": ["身體所造成的損傷只有在電流入口及出口處", "交流電造成的傷害較直流電嚴重", "對電流阻力越大的組織越不易造成損傷", "骨骼的電流阻力小於血管"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112110&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112110-102-0203-046", "year": 112, "session": "第二次", "no": 46, "stem": "46 熱燒傷病人進行水療法時之護理措施，下列何者最適宜？", "options": ["水溫調配維持32～34℃，以減少傷口疼痛", "水池中加入beta-iodine 30～50 ppm，以抑制細菌生長", "水池中每公升加入0.85 公克的食鹽，以補充流失的電解質", "水療時間每次以一小時為宜，使痂皮鬆脫"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112110&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "113100-102-0203-028", "year": 113, "session": "第二次", "no": 28, "stem": "28  40 歲男性病人，入院診斷為二度燒傷，依照帕克蘭公式計算需給予12,000 c.c. 液體復甦治療，在燒傷後\n  的第一個8 小時內需補充完成多少輸液？", "options": ["3,000 c.c.", "4,000 c.c.", "6,000 c.c.", "12,000 c.c."], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "113180-101-0103-027", "year": 113, "session": "第三次", "no": 27, "stem": "27 有關燒傷病人輔助使用高壓氧治療之作用，下列何者最適宜？", "options": ["提升病人的意識程度", "活化組織促進上皮細胞生長", "促進皮膚毛髮生長", "改善病人憂鬱狀態"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "114170-101-0103-026", "year": 114, "session": "第三次", "no": 26, "stem": "26 有關帶狀疱疹，下列敘述何者最適當？①感染痊癒後通常會有終生免疫力 ②避免摩擦造成水泡破裂，建議穿\n\n  寬鬆柔軟衣服 ③當有神經痛症狀，可給予適當的止痛藥物 ④未患過水痘的人，應避免與帶狀疱疹病人接觸", "options": ["①②③", "②③④", "①②④", "①③④\n代號：3101\n頁次：4－3"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114170&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "114170-101-0103-027", "year": 114, "session": "第三次", "no": 27, "stem": "27 成人燒傷部位與範圍包括左上肢全部、左下肢正面及軀幹正面，依據九法則評估其燒傷面積為何？", "options": ["18%", "27%", "30%", "36%"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114170&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "115100-102-0203-008", "year": 115, "session": "第二次", "no": 8, "stem": "8 有關痔瘡的敘述，下列何者正確？①教導病人手術後一週開始溫水坐浴，促進傷口癒合 ②內痔與外痔的\n  分界線是肛門黏膜與上皮相接的齒狀線（dental line） ③內痔區域是由自主神經所支配、外痔區域則是由\n  體／知覺神經所支配 ④痔瘡切除術後教導病人採仰臥，利用填塞於直腸內的敷料加壓傷口止血", "options": ["①②", "①④", "②③", "③④"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=115100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "115100-102-0203-029", "year": 115, "session": "第二次", "no": 29, "stem": "29 簡先生6 小時前車禍意外造成全身40%的熱燒傷，下列敘述何者正確？", "options": ["腎絲球過濾（GFR）上升", "代謝性鹼中毒", "血糖升高", "血鉀下降"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=115100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "115100-102-0203-030", "year": 115, "session": "第二次", "no": 30, "stem": "30 異位性皮膚炎病人血液中會出現下列何種免疫球蛋白升高？", "options": ["IgA", "IgE", "IgG", "IgM"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=115100&c=102&s=0203&q=1", "status": "needs_visual_review"}], "9": [{"id": "106030-106-0503-004", "year": 106, "session": "第一次", "no": 4, "stem": "4 有關頸部脊髓損傷的神經性休克徵象，下列何者正確？", "options": ["多尿", "臉潮紅、鼻道充血", "肌肉顫動", "體溫下降"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106030-106-0503-026", "year": 106, "session": "第一次", "no": 26, "stem": "26 有關心因性休克造成之血流動力學變化，下列何者正確？", "options": ["中心靜脈壓下降", "右心室壓力下降", "肺動脈楔壓上升", "心輸出量上升"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106030-106-0503-075", "year": 106, "session": "第一次", "no": 75, "stem": "75 有關心肺復甦術時胸部按壓之敘述，下列何者錯誤？", "options": ["位置為胸部兩乳頭連線中央", "速度維持每分鐘80 次", "成人深度至少5 公分", "更換急救人員時中斷時間以10 秒為限"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106030-106-0503-076", "year": 106, "session": "第一次", "no": 76, "stem": "76  有關巴拉刈（Paraquat）中毒之敘述，下列何者錯誤？", "options": ["食入後嘴唇、口腔黏膜及咽部會產生潰爛", "24 小時內會出現急性腎衰竭", "立即給予氧氣使用以預防缺氧", "儘速協助胃灌洗"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106030-106-0503-077", "year": 106, "session": "第一次", "no": 77, "stem": "77 有關食物中毒後有腦部神經症狀，包括複視、眼瞼下垂、視力模糊、吞嚥困難是屬於下列那一類食\n\n  物中毒？", "options": ["沙門氏桿菌", "葡萄球菌", "大腸桿菌", "肉毒桿菌"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106030-106-0503-078", "year": 106, "session": "第一次", "no": 78, "stem": "78 有關大量傷患事故檢傷分類 START（Simple Triage and Rapid Treatment）之敘述，下列何者錯誤？", "options": ["救難現場的救治順序依檢傷分類分為四級，且以顏色區分", "若無脈搏或橈動脈微弱、末梢血流回充＞2 秒者，則繫上紅色牌子為第一優先處理", "若可自行行走者，則繫上黃色牌子為第三優先處理", "評估意識時若傷患無法聽指令者，則繫上紅色牌子為第一優先處理"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-042", "year": 106, "session": "第二次", "no": 42, "stem": "42 有關一氧化碳中毒的臨床表徵，下列何者正確？", "options": ["吐氣喘鳴聲及鼻翼煽動", "黏膜出現櫻桃紅", "痰液含有煤炭", "咳嗽"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-072", "year": 106, "session": "第二次", "no": 72, "stem": "72 為路倒者執行心肺腦復甦術期間，當接上電擊器顯示為心搏停止，此時應執行之急救措施，下列何者正確？", "options": ["立即開始給予360 焦耳之電擊以去顫", "立即開始給予200 焦耳之電擊以去顫", "先貼上膠狀之電擊貼片", "繼續執行心肺腦復甦術"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106110-106-0503-074", "year": 106, "session": "第二次", "no": 74, "stem": "74 有關促進中毒物質排出之方法，不包括下列何者？", "options": ["使用瀉藥", "酸化尿液", "使用人工呼吸器", "鹼化尿液"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-002", "year": 106, "session": "第二次", "no": 2, "stem": "2 周先生騎機車被酒駕汽車追撞，導致頭部創傷，GCS 評估結果為E1V2M3，此分數所代表的意義，\n\n  下列敘述何者正確？", "options": ["給予疼痛刺激眼睛均無反應", "給予疼痛刺激發出單字或片語", "給予疼痛刺激會將疼痛點移除", "表示病人處深度昏迷狀態，預後較差"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-075", "year": 106, "session": "第二次", "no": 75, "stem": "75  高先生78 歲，因反應變遲緩而送至急診，檢查發現體溫39℃、脈搏122 次／分鐘、呼吸30 次／分\n\n  鐘、血壓 90/60 mmHg、血氧飽和度為93%、GCS 評估結果為E2V3M5、白血球15,000/μL。依據目\n\n  前之觀察與檢查數據，以臺灣急診檢傷急迫度分級量表（TTAS）判斷病人級數，下列何者正確？", "options": ["第一級", "第二級", "第三級", "第四級"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "106111-106-0503-078", "year": 106, "session": "第二次", "no": 78, "stem": "78 有關一氧化碳中毒之敘述，下列何者錯誤？", "options": ["一氧化碳與血紅素的親和力高過氧氣與血紅素的20 倍", "當血中 COHb＞10%時，病人會出現中毒症狀", "一氧化碳的半衰期在高壓氧治療中，會縮短至30 分鐘", "當血中COHb＞60%時，病人會昏迷甚至死亡"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106111&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-003", "year": 107, "session": "第一次", "no": 3, "stem": "3  姚先生被車子碾過造成T12，L1～L3 脊髓損傷，到達急診後出現脊髓休克，下列敘述何者錯誤？", "options": ["無法控制大小便", "無法自行呼吸", "腸道蠕動降低造成腹脹", "肛門反射消失"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-073", "year": 107, "session": "第一次", "no": 73, "stem": "73 有關巴拉刈中毒之敘述，下列何者錯誤？", "options": ["對細胞膜及結締組織產生嚴重破壞", "腎臟與肝臟最先受到傷害", "含氧量最高的肺臟受到傷害最嚴重", "主要經由肝臟排泄"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-075", "year": 107, "session": "第一次", "no": 75, "stem": "75 在急救過程中需為成年病人放置氣管內插管之敘述，下列何者錯誤？", "options": ["依據病人的性別來做選擇", "氣管內管由口插入深度大約為25～27 公分", "插管過程中，若血氧濃度下降至80%，應立即停止插管並給病人100%氧氣吸入3～5 分鐘後，再\n\n   嘗試插管", "插管過程中可執行沙立克操作法（Sellick Maneauver）以防止發生食物逆流導致吸入性危險"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107030-106-0503-076", "year": 107, "session": "第一次", "no": 76, "stem": "76 中毒病人最優先之處置原則，下列何者正確？", "options": ["確定中毒物質", "清除中毒物質", "穩定生命徵象", "查詢中毒物質之訊息"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107110-106-0503-077", "year": 107, "session": "第二次", "no": 77, "stem": "77 有關有機磷中毒臨床處置之敘述，下列何者錯誤？", "options": ["維持呼吸道通暢，必要時給與插管", "morphine 是有機磷中毒的拮抗劑", "協助除去被污染的衣物並協助沐浴及洗頭髮", "照護此類病人需做好防護設施，戴口罩、手套及穿隔離衣"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "107110-106-0503-080", "year": 107, "session": "第二次", "no": 80, "stem": "80 有關血中賀爾蒙於休克代償機轉中之變化，下列何者錯誤？", "options": ["醛固酮aldosterone 上升", "促腎上腺皮質激素（ACTH）上升", "腎素renin 下降", "抗利尿激素（ADH）上升"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-030", "year": 108, "session": "第一次", "no": 30, "stem": "30 有關毛地黃中毒症狀，下列何者正確？①腹瀉 ②便祕 ③噁心嘔吐 ④黃色視覺 ⑤紅色視覺\n  ⑥心跳變快", "options": ["①③④", "①⑤⑥", "②③⑤", "②④⑥"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108020-106-0503-078", "year": 108, "session": "第一次", "no": 78, "stem": "78 有關一氧化碳中毒病人之護理措施，下列何者正確？", "options": ["給予高濃度氧氣", "協助病人活動以促進一氧化碳排出", "應立即協助中毒者催吐", "提供解毒劑"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108020&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108110-106-0503-075", "year": 108, "session": "第二次", "no": 75, "stem": "75 病人發生休克時對肝臟系統之影響不包括下列何者？", "options": ["早期出現血中葡萄糖增加", "漸進期出現代謝性鹼中毒", "漸進期出現乳酸轉換下降", "漸進期出現血中葡萄糖下降"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108110-106-0503-076", "year": 108, "session": "第二次", "no": 76, "stem": "76 有關食物中毒之敘述，下列何者錯誤？", "options": ["食物中毒多指食用遭細菌污染之食物或誤食野生蕈造成", "葡萄球菌中毒是最常見之食物中毒", "食物中毒之症狀嚴重度與食入污染物的量與內毒素含量有正相關", "處理食物中毒休克病人時，應最先了解是何種食物導致病人出現腹瀉與脫水"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "108110-106-0503-078", "year": 108, "session": "第二次", "no": 78, "stem": "78 有關自動體外心臟去顫器（AED）之敘述，下列何者錯誤？", "options": ["政府立法於公共場所設置AED 以即時搶救病人，同時讓施救者受到免責之保障", "使用時機為病人出現心室纖維顫動或是無脈搏心室心搏過速", "使用時有整流與去顫兩種功能", "具有語音提示正確操作機器步驟之功能"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-001", "year": 109, "session": "第一次", "no": 1, "stem": "1  有關脊髓休克（Spinal shock）的敘述，下列何者錯誤？", "options": ["病人的肛門反射正常", "受傷部位以下的肌肉力量消失", "受傷部位以下的溫、痛、觸覺消失", "腸蠕動下降或出現麻痺性腸阻塞"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109030-106-0503-075", "year": 109, "session": "第一次", "no": 75, "stem": "75 有關肉毒桿菌中毒的敘述，下列何者錯誤？", "options": ["主因食入被臘腸桿菌產生的外毒素所污染的食物", "除腸胃道症狀外，會有高燒", "除腸胃道症狀外，會有視力模糊、複視等神經方面的症狀", "對中毒病人除須注射抗毒素外，尚須施以洗胃灌腸以中和毒素或排出腸道毒素"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109030&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-008", "year": 109, "session": "第二次", "no": 8, "stem": "8 陳先生早上騎機車出門上班時，於十字路口與計程車擦撞倒地，同時頭部撞到地面，當時意識清楚但\n  有多處擦傷及撕裂傷，由救護車送至急診室，當醫師正在縫合傷口時，陳先生突然喪失意識，其最大\n  可能為下列何種頭部創傷？", "options": ["硬膜上出血", "蜘蛛膜下腔出血", "硬膜下出血", "顱內出血"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-028", "year": 109, "session": "第二次", "no": 28, "stem": "28 造成心因性休克的主要原因，不包括下列何者？", "options": ["心律不整", "心肌梗塞", "瓣膜性心臟病", "創傷致出血過多"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "109110-106-0503-076", "year": 109, "session": "第二次", "no": 76, "stem": "76 有關「臺灣急診檢傷與急迫度分級量表」（TTAS）的敘述，下列何者正確？", "options": ["復甦急救等級：每10 分鐘評估一次", "非緊急等級：每120 分鐘評估一次", "緊急等級是屬於第二級", "緊急等級：每90 分鐘評估一次"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109110&c=106&s=0503&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-077", "year": 110, "session": "第一次", "no": 77, "stem": "77 依據「臺灣急診檢傷與急迫度分級量表」（TTAS），病人出現中樞性疼痛程度為4～7 分，級數應為\n  下列何者？", "options": ["一級", "二級", "三級", "四級"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110030-104-0303-079", "year": 110, "session": "第一次", "no": 79, "stem": "79 有關休克初期身體啟動之正常代償機轉，下列何者錯誤？", "options": ["副交感神經釋放腎上腺素使心跳加快", "腎臟血流減少", "四肢溫度降低", "全身末梢血管收縮"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-076", "year": 110, "session": "第二次", "no": 76, "stem": "76 下列何種休克病人，根據其導因應優先考慮給與水分或血品之輸注？", "options": ["心因性休克", "低血容積性休克", "過敏性休克", "敗血性休克"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-078", "year": 110, "session": "第二次", "no": 78, "stem": "78 下列何者為病人在休克進行期或不可逆期出現的表徵？", "options": ["心跳70～80 次／分", "呼吸12～15 次／分", "血中pH＞7.50", "血中PaCO2＞40 mmHg"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "110110-104-0303-079", "year": 110, "session": "第二次", "no": 79, "stem": "79 有關急救藥物主要治療效果的敘述，下列何者錯誤？", "options": ["Amiodarone 主要用於治療病人持續出現心室纖維顫動或是無脈搏心室心搏過速", "Atropine 多用於心搏過緩或心臟收縮不全", "Dopamine 多用於治療低血壓", "Sodium Bicarbonate（NaHCO3）多用於治療鹼血症"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111030-104-0303-006", "year": 111, "session": "第一次", "no": 6, "stem": "6 有關頭部創傷之敘述，下列何者正確？", "options": ["腦震盪是因外力造成暫時性的神經功能缺失，且腦組織有實質性的損傷", "腦挫傷是因沒有腦組織的實質性損傷，所以受傷後常會出現腦震盪症候群", "若出現鼻漏且確認是腦脊髓液，表示病人的硬腦膜受損", "有鼻漏或耳漏的病人通常要儘快用抽吸管抽吸乾淨"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111030-104-0303-030", "year": 111, "session": "第一次", "no": 30, "stem": "30 有關心因性休克之敘述，下列何者錯誤？", "options": ["心臟幫浦功能障礙造成循環衰竭", "最常見之致病原因為心肌梗塞", "最常見之症狀為呼吸停止", "心輸出量不符身體組織所需"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111030-104-0303-076", "year": 111, "session": "第一次", "no": 76, "stem": "76 下列何者不是休克時會發生之代償機轉？", "options": ["刺激交感神經分泌腎上腺素，造成血管收縮", "刺激交感神經，使呼吸加速及加深", "刺激內分泌系統分泌血管緊縮素，促進血管收縮", "刺激消化道系統，促進腸胃蠕動"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111030-104-0303-077", "year": 111, "session": "第一次", "no": 77, "stem": "77 下列何種情況最可能引發神經性休克？", "options": ["蜜蜂螫傷引發休克", "張力性氣胸造成休克", "心肌梗塞造成休克", "車禍脊髓受損造成休克"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111030&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-002", "year": 111, "session": "第二次", "no": 2, "stem": "2 有關脊髓損傷後脊髓休克期照護的敘述，下列何者錯誤？", "options": ["肛門反射出現表示脊髓休克期已結束", "可以插鼻胃管引流胃液減壓", "可使用高劑量類固醇治療以減輕脊髓水腫", "經電腦斷層攝影可確診為完全或不完全脊髓損傷"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-076", "year": 111, "session": "第二次", "no": 76, "stem": "76 有關骨折病人到院前急救處理原則，下列何者為最優先的處置？", "options": ["給予疼痛處理", "將骨折部位復位", "固定骨折部位", "給予熱敷處理"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-077", "year": 111, "session": "第二次", "no": 77, "stem": "77 有關服用有機磷中毒的護理措施，下列何者錯誤？", "options": ["維持呼吸道通暢", "清醒者可進行催吐以減少有機磷之吸收", "照顧病人時要穿戴防護措施，包括口罩、手套、隔離衣以及適當通風", "使用Atropine 靜脈注射時，維持病人心跳在60 次／分鐘左右"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "111110-104-0303-078", "year": 111, "session": "第二次", "no": 78, "stem": "78 有關矯正休克病人低血壓的護理措施，下列何者錯誤？", "options": ["應優先輸血以恢復全身循環血量", "放置靜脈導管時應優先使用大管徑的導管", "靜脈導管放置應優先考慮中心靜脈導管", "密切注意病人血壓的變化"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111110&c=104&s=0303&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-075", "year": 112, "session": "第一次", "no": 75, "stem": "75 有關急救使用手壓式甦醒球面罩（Ambu Bag mask）給與人工呼吸的敘述，下列何者正確？", "options": ["當病人SPO2 95%時應該使用", "面罩較尖的部位應對準病人下巴", "氧氣流速調整至12～15 公升／分鐘", "一手使面罩密合病人口鼻，另一手應儘量完全壓扁球囊"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-076", "year": 112, "session": "第一次", "no": 76, "stem": "76 有關施行心肺復甦術（CPR）成功徵象的敘述，下列何者正確？①四肢有動作反應 ②有自發性呼吸\n\n  ③刺激眼瞼會眨眼 ④瞳孔對光反射固定", "options": ["①②③", "①②④", "①③④", "②③④"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112030-102-0203-077", "year": 112, "session": "第一次", "no": 77, "stem": "77 下列何類休克有皮膚潮紅、溫暖的臨床徵象？①低血容性 ②敗血性 ③心因性 ④神經性", "options": ["①②", "①③", "②④", "③④"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112030&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112110-102-0203-006", "year": 112, "session": "第二次", "no": 6, "stem": "6 張先生因高處跌下導致脊髓損傷住院，護理師可經由下列何種反射出現，而知張先生已渡過脊髓休克\n\n  期？", "options": ["作嘔反射", "肛門反射", "頭眼反射", "角膜反射"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112110&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "112180-101-0103-048", "year": 112, "session": "第三次", "no": 48, "stem": "48 有關自動體外心臟電擊去顫器（AED）的操作敘述，下列何者錯誤？", "options": ["電擊貼片須貼在病人的右鎖骨下及左乳旁胸部", "若胸毛太多無法黏上電擊片，則以手按壓住電擊片電擊以增加導電", "聽到指示「按下電擊按鈕」應確認所有人無觸碰病人再按下電擊按鈕", "若病人身體濕，應先擦乾再貼貼片"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "112180-101-0103-049", "year": 112, "session": "第三次", "no": 49, "stem": "49 病人體重77 公斤，摔車導致右側大腿變形骨折，血流不止，119 緊急救護員給予緊急處理後送到急診，病\n   人體溫35.8℃、心跳136 次／分、呼吸34 次／分、血壓80/58 mmHg，皮膚冷潮濕，微血管充填時間大於\n    2 秒，呈現焦慮情緒。依據上述資料，病人呈現的休克種類，下列何者正確？", "options": ["低血容積性休克", "血管性休克", "神經性休克", "心因性休克"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "112180-101-0103-050", "year": 112, "session": "第三次", "no": 50, "stem": "50 根據2020 年美國心臟醫學會（AHA）公告的「生存之鏈（chain of survival）」急救步驟，發生於醫院內心\n  臟停止的照護（in hospital cardiac arrest, IHCA），其急救重點次序，下列何者正確？①即早辨識和預防\n  ②緊急應變系統啟動 ③施行高品質CPR ④去顫 ⑤心臟停止後照護 ⑥復原", "options": ["①→②→③→④→⑤→⑥", "①→③→⑤→②→④→⑥", "①→②→④→③→⑤→⑥", "①→④→③→②→⑤→⑥"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "113100-102-0203-047", "year": 113, "session": "第二次", "no": 47, "stem": "47 當一人施行心肺復甦術（CPR）時，下列何者應先施行2 分鐘的急救後再求救？", "options": ["心臟衰竭呼吸停止", "急性腦中風昏迷", "成人野溪溺水", "糖尿病酮酸中毒昏迷"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "113100-102-0203-048", "year": 113, "session": "第二次", "no": 48, "stem": "48 有關心因性休克的敘述，下列何者正確？", "options": ["主要是感染或血管通透性改變造成", "常見於外傷造成主動脈剝離、張力性氣胸", "因創傷出血過多造成心臟回血量減少", "主動脈內氣球幫浦（IABP）是重要治療方式之一"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "113100-102-0203-049", "year": 113, "session": "第二次", "no": 49, "stem": "49 當意識不清病人被送至急診，檢查瞳孔兩側等大且小於2.0 mm，可能為下列何者中毒？①有機磷 ②安非他命\n  ③鴉片 ④古柯鹼", "options": ["①②", "①③", "②④", "③④"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "113100-102-0203-050", "year": 113, "session": "第二次", "no": 50, "stem": "50  有關臘腸桿菌（Clostridium botulinum）中毒的預防、症狀與治療之敘述，下列何者正確？", "options": ["食物可在攝氏100 度下加熱10 分鐘以破壞臘腸桿菌", "中毒後首先出現神經方面症狀，如視力模糊、瞳孔放大、吞嚥困難等症狀", "目前無有效的抗毒素與抗生素治療", "臘腸桿菌於真空包裝食品中無法存活"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "113180-101-0103-047", "year": 113, "session": "第三次", "no": 47, "stem": "47 有關敗血性休克導致的系統性炎性反應症候群（SIRS）其診斷的四個條件中，需含二項或以上，下列條件\n  何者正確？①體溫大於38℃或小於36℃ ②心跳小於60 次／分 ③呼吸速率大於20 次／分，或PaCO2\n  小於40 mmHg ④白血球大於12000/uL 或小於4000/uL", "options": ["①②", "①④", "②③", "③④"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113180&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "114100-102-0203-005", "year": 114, "session": "第二次", "no": 5, "stem": "5 有關病人因頸椎脊髓損傷處於脊髓休克期的敘述，下列何者錯誤？", "options": ["心跳50 次／分、呼吸15 次／分、血壓160/100 mmHg", "主要是因喪失自主神經的控制", "受傷部位以下的所有運動、感覺、反射可能減弱或消失", "出現尿滯留及腸蠕動下降"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "114170-101-0103-037", "year": 114, "session": "第三次", "no": 37, "stem": "37 有關低血容性休克分期的進行期，下列敘述何者最不適當？", "options": ["身體代償機轉已無法逆轉休克的進行，會導致皮膚濕冷、體溫下降", "心輸出量下降、血壓下降，可以選擇輸注等張0.9%生理食鹽水", "造成呼吸性酸中毒、乳酸轉換上升，需要避免輸注乳酸林格氏輸液", "會造成血中尿素氮（BUN）上升及肌酸酐（creatinine）上升"], "answer": "C", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114170&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "114170-101-0103-046", "year": 114, "session": "第三次", "no": 46, "stem": "46 小明在登山途中不慎被一條青色的蛇咬傷，下列敘述何者最適當？", "options": ["辨識蛇的形狀及顏色，並去除身上會影響血循的物品", "割開傷口，並以嘴吸出毒液", "以酒精消毒咬傷之傷口，並給予傷口冰敷", "盡力把蛇打死，帶到急診室以辨別是否為毒蛇"], "answer": "A", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114170&c=101&s=0103&q=1", "status": "needs_visual_review"}, {"id": "115100-102-0203-048", "year": 115, "session": "第二次", "no": 48, "stem": "48 有關中毒症狀與處置之敘述，下列何者正確？", "options": ["誤食鹽酸者不催吐，可以喝大量的水或牛奶來稀釋中和鹽酸濃度，以減少毒物吸收", "一氧化碳中毒跟潛水夫病的緊急處理原則一樣，都需給與100%氧氣及高壓氧治療", "肉毒桿菌中毒與金黃色葡萄球菌中毒的發作時間都在食物食用後4～6 小時發作", "安非他命與鴉片類藥物都會有瞳孔縮小的症狀，可以使用naloxone 作為解毒劑"], "answer": "B", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=115100&c=102&s=0203&q=1", "status": "needs_visual_review"}, {"id": "115100-102-0203-050", "year": 115, "session": "第二次", "no": 50, "stem": "50 有關休克病人處置後病況改善的表徵，下列何者最適宜？", "options": ["心跳速率由120 次／分降為60 次／分", "65 公斤重的病人，尿量28 mL/小時", "使用dopamine 收縮壓為90 mmHg", "GCS：E3V3M5 變為E3V5M6"], "answer": "D", "url": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=115100&c=102&s=0203&q=1", "status": "needs_visual_review"}]}, "source": "考選部護理師國考題庫 106–115 年 內外科護理學"};